 27→// GetRewindPoints returns available rewind points.
 28→// Uses checkpoint.GitStore.ListTemporaryCheckpoints for reading from shadow branches.
 29→func (s *ManualCommitStrategy) GetRewindPoints(ctx context.Context, limit int) ([]RewindPoint, error) {
 30→	repo, err := OpenRepository(ctx)
 31→	if err != nil {
 32→		return nil, fmt.Errorf("failed to open git repository: %w", err)
 33→	}
 34→
 35→	// Get checkpoint store
 36→	store, err := s.getCheckpointStore()
 37→	if err != nil {
 38→		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
 39→	}
 40→
 41→	// Get current HEAD to find matching shadow branch
 42→	head, err := repo.Head()
 43→	if err != nil {
 44→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
 45→	}
 46→
 47→	// Find sessions for current HEAD
 48→	sessions, err := s.findSessionsForCommit(ctx, head.Hash().String())
 49→	if err != nil {
 50→		// Log error but continue to check for logs-only points
 51→		sessions = nil
 52→	}
 53→
 54→	var allPoints []RewindPoint
 55→
 56→	// Collect checkpoint points from active sessions using checkpoint.GitStore
 57→	// Cache session prompts by session ID to avoid re-reading the same prompt file
 58→	sessionPrompts := make(map[string]string)
 59→
 60→	for _, state := range sessions {
 61→		checkpoints, err := store.ListTemporaryCheckpoints(ctx, state.BaseCommit, state.WorktreeID, state.SessionID, limit)
 62→		if err != nil {
 63→			continue // Error reading checkpoints, skip this session
 64→		}
 65→
 66→		for _, cp := range checkpoints {
 67→			// Get session prompt (cached by session ID)
 68→			sessionPrompt, ok := sessionPrompts[cp.SessionID]
 69→			if !ok {
 70→				sessionPrompt = readSessionPrompt(repo, cp.CommitHash, cp.MetadataDir)
 71→				sessionPrompts[cp.SessionID] = sessionPrompt
 72→			}
 73→
 74→			allPoints = append(allPoints, RewindPoint{
 75→				ID:               cp.CommitHash.String(),
 76→				Message:          cp.Message,
 77→				MetadataDir:      cp.MetadataDir,
 78→				Date:             cp.Timestamp,
 79→				IsTaskCheckpoint: cp.IsTaskCheckpoint,
 80→				ToolUseID:        cp.ToolUseID,
 81→				SessionID:        cp.SessionID,
 82→				SessionPrompt:    sessionPrompt,
 83→				Agent:            state.AgentType,
 84→			})
 85→		}
 86→	}
 87→
 88→	// Sort by date, most recent first
 89→	sort.Slice(allPoints, func(i, j int) bool {
 90→		return allPoints[i].Date.After(allPoints[j].Date)
 91→	})
 92→
 93→	if len(allPoints) > limit {
 94→		allPoints = allPoints[:limit]
 95→	}
 96→
 97→	// Also include logs-only points from commit history
 98→	logsOnlyPoints, err := s.GetLogsOnlyRewindPoints(ctx, limit)
 99→	if err == nil && len(logsOnlyPoints) > 0 {
100→		// Build set of existing point IDs for deduplication
101→		existingIDs := make(map[string]bool)
102→		for _, p := range allPoints {
103→			existingIDs[p.ID] = true
104→		}
105→
106→		// Add logs-only points that aren't already in the list
107→		for _, p := range logsOnlyPoints {
108→			if !existingIDs[p.ID] {
109→				allPoints = append(allPoints, p)
110→			}
111→		}
112→
113→		// Re-sort by date
114→		sort.Slice(allPoints, func(i, j int) bool {
115→			return allPoints[i].Date.After(allPoints[j].Date)
116→		})
117→
118→		// Re-trim to limit
119→		if len(allPoints) > limit {
120→			allPoints = allPoints[:limit]
121→		}
122→	}
123→
124→	return allPoints, nil
125→}
