457→// and will be replaced by the checkpoint contents. Returns true with a warning message showing
458→// what changes will be reverted.
459→func (s *ManualCommitStrategy) CanRewind(ctx context.Context) (bool, string, error) {
460→	return checkCanRewindWithWarning(ctx)
461→}
