577→// RestoreLogsOnly restores session logs from a logs-only rewind point.
578→// This fetches the transcript from entire/checkpoints/v1 and writes it to the agent's session directory.
579→// Does not modify the working directory.
580→// When multiple sessions were condensed to the same checkpoint, ALL sessions are restored.
581→// If force is false, prompts for confirmation when local logs have newer timestamps.
582→// Returns info about each restored session so callers can print correct per-session resume commands.
583→func (s *ManualCommitStrategy) RestoreLogsOnly(ctx context.Context, point RewindPoint, force bool) ([]RestoredSession, error) {
584→	if !point.IsLogsOnly {
585→		return nil, errors.New("not a logs-only rewind point")
586→	}
587→
588→	if point.CheckpointID.IsEmpty() {
589→		return nil, errors.New("missing checkpoint ID")
590→	}
591→
592→	// Get checkpoint store
593→	store, err := s.getCheckpointStore()
594→	if err != nil {
595→		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
596→	}
597→
598→	// Read checkpoint summary to get session count
599→	summary, err := store.ReadCommitted(ctx, point.CheckpointID)
600→	if err != nil {
601→		return nil, fmt.Errorf("failed to read checkpoint: %w", err)
602→	}
603→	if summary == nil {
604→		return nil, fmt.Errorf("checkpoint not found: %s", point.CheckpointID)
605→	}
606→
607→	// Get worktree root for agent session directory lookup
608→	repoRoot, err := paths.WorktreeRoot(ctx)
609→	if err != nil {
610→		return nil, fmt.Errorf("failed to get worktree root: %w", err)
611→	}
612→
613→	// Check for newer local logs if not forcing
614→	if !force {
615→		sessions := s.classifySessionsForRestore(ctx, repoRoot, store, point.CheckpointID, summary)
616→		hasConflicts := false
617→		for _, sess := range sessions {
618→			if sess.Status == StatusLocalNewer {
619→				hasConflicts = true
620→				break
621→			}
622→		}
623→		if hasConflicts {
624→			shouldOverwrite, promptErr := PromptOverwriteNewerLogs(sessions)
625→			if promptErr != nil {
626→				return nil, promptErr
627→			}
628→			if !shouldOverwrite {
629→				fmt.Fprintf(os.Stderr, "Resume cancelled. Local session logs preserved.\n")
630→				return nil, nil
631→			}
632→		}
633→	}
634→
635→	// Count sessions to restore
636→	totalSessions := len(summary.Sessions)
637→	if totalSessions > 1 {
638→		fmt.Fprintf(os.Stderr, "Restoring %d sessions from checkpoint:\n", totalSessions)
639→	}
640→
641→	// Restore all sessions (oldest to newest, using 0-based indexing)
642→	var restored []RestoredSession
643→	for i := range totalSessions {
644→		content, readErr := store.ReadSessionContent(ctx, point.CheckpointID, i)
645→		if readErr != nil {
646→			fmt.Fprintf(os.Stderr, "  Warning: failed to read session %d: %v\n", i, readErr)
647→			continue
648→		}
649→		if content == nil || len(content.Transcript) == 0 {
650→			continue
651→		}
652→
653→		sessionID := content.Metadata.SessionID
654→		if sessionID == "" {
655→			fmt.Fprintf(os.Stderr, "  Warning: session %d has no session ID, skipping\n", i)
656→			continue
657→		}
658→
659→		// Resolve per-session agent from metadata — skip if agent is unknown
660→		if content.Metadata.Agent == "" {
661→			fmt.Fprintf(os.Stderr, "  Warning: session %d (%s) has no agent metadata, skipping (cannot determine target directory)\n", i, sessionID)
662→			continue
663→		}
664→		sessionAgent, agErr := ResolveAgentForRewind(content.Metadata.Agent)
665→		if agErr != nil {
666→			fmt.Fprintf(os.Stderr, "  Warning: session %d (%s) has unknown agent %q, skipping\n", i, sessionID, content.Metadata.Agent)
667→			continue
668→		}
669→
670→		// Compute transcript path from current repo location for cross-machine portability.
671→		sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
672→		if dirErr != nil {
673→			fmt.Fprintf(os.Stderr, "  Warning: failed to get session dir for session %d: %v\n", i, dirErr)
674→			continue
675→		}
676→		sessionFile := sessionAgent.ResolveSessionFile(sessionAgentDir, sessionID)
677→
678→		// Get first prompt for display
679→		promptPreview := ExtractFirstPrompt(content.Prompts)
680→
681→		if totalSessions > 1 {
682→			isLatest := i == totalSessions-1
683→			if promptPreview != "" {
684→				if isLatest {
685→					fmt.Fprintf(os.Stderr, "  Session %d (latest): %s\n", i+1, promptPreview)
686→				} else {
687→					fmt.Fprintf(os.Stderr, "  Session %d: %s\n", i+1, promptPreview)
688→				}
689→			}
690→			fmt.Fprintf(os.Stderr, "    Writing to: %s\n", sessionFile)
691→		} else {
692→			fmt.Fprintf(os.Stderr, "Writing transcript to: %s\n", sessionFile)
693→		}
694→
695→		// Ensure parent directory exists (session file may be in a different dir than sessionAgentDir)
696→		if mkdirErr := os.MkdirAll(filepath.Dir(sessionFile), 0o750); mkdirErr != nil {
697→			fmt.Fprintf(os.Stderr, "    Warning: failed to create directory: %v\n", mkdirErr)
698→			continue
699→		}
700→
701→		agentSession := &agent.AgentSession{
702→			SessionID:  sessionID,
703→			AgentName:  sessionAgent.Name(),
704→			RepoPath:   repoRoot,
705→			SessionRef: sessionFile,
706→			NativeData: content.Transcript,
707→		}
708→		if writeErr := sessionAgent.WriteSession(ctx, agentSession); writeErr != nil {
709→			if totalSessions > 1 {
710→				fmt.Fprintf(os.Stderr, "    Warning: failed to write session: %v\n", writeErr)
711→				continue
712→			}
713→			return nil, fmt.Errorf("failed to write session: %w", writeErr)
714→		}
715→
716→		restored = append(restored, RestoredSession{
717→			SessionID: sessionID,
718→			Agent:     sessionAgent.Type(),
719→			Prompt:    promptPreview,
720→			CreatedAt: content.Metadata.CreatedAt,
721→		})
722→	}
723→
724→	return restored, nil
725→}
