 12→// TestRewind_FullWorkflow tests the complete rewind workflow for all strategies.
 13→// From the user's perspective, all strategies should behave identically:
 14→// - Sessions create rewind points
 15→// - Rewind restores file contents
 16→// - Transcript is available for session resumption
 17→//
 18→// All strategies use a single session with multiple checkpoints, simulating
 19→// one continuous Claude session with multiple prompts.
 20→func TestRewind_FullWorkflow(t *testing.T) {
 21→	t.Parallel()
 22→	env := NewFeatureBranchEnv(t)
 23→	// Use same session for all checkpoints (works for all strategies)
 24→	session := env.NewSession()
 25→
 26→	// Checkpoint 1: Add ruby script
 27→	if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
 28→		t.Fatalf("SimulateUserPromptSubmit failed: %v", err)
 29→	}
 30→
 31→	rubyV1 := "puts rand(100)"
 32→	env.WriteFile("random.rb", rubyV1)
 33→
 34→	session.CreateTranscript(
 35→		"Add a ruby script that returns a random number",
 36→		[]FileChange{{Path: "random.rb", Content: rubyV1}},
 37→	)
 38→	if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
 39→		t.Fatalf("SimulateStop checkpoint1 failed: %v", err)
 40→	}
 41→
 42→	// Checkpoint 2: Change to red
 43→	if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
 44→		t.Fatalf("SimulateUserPromptSubmit failed: %v", err)
 45→	}
 46→
 47→	rubyV2 := `puts "\e[31m#{rand(100)}\e[0m"`
 48→	env.WriteFile("random.rb", rubyV2)
 49→
 50→	session.CreateTranscript(
 51→		"Change the output to use red color",
 52→		[]FileChange{{Path: "random.rb", Content: rubyV2}},
 53→	)
 54→	if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
 55→		t.Fatalf("SimulateStop checkpoint2 failed: %v", err)
 56→	}
 57→
 58→	// Checkpoint 3: Change to green
 59→	if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
 60→		t.Fatalf("SimulateUserPromptSubmit failed: %v", err)
 61→	}
 62→
 63→	rubyV3 := `puts "\e[32m#{rand(100)}\e[0m"`
 64→	env.WriteFile("random.rb", rubyV3)
 65→
 66→	session.CreateTranscript(
 67→		"Change the output to use green color",
 68→		[]FileChange{{Path: "random.rb", Content: rubyV3}},
 69→	)
 70→	if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
 71→		t.Fatalf("SimulateStop checkpoint3 failed: %v", err)
 72→	}
 73→
 74→	// Verify current state is green version
 75→	content := env.ReadFile("random.rb")
 76→	if content != rubyV3 {
 77→		t.Errorf("before rewind: got %q, want %q", content, rubyV3)
 78→	}
 79→
 80→	// Get rewind points - should have 3
 81→	points := env.GetRewindPoints()
 82→	if len(points) != 3 {
 83→		t.Fatalf("expected 3 rewind points, got %d", len(points))
 84→	}
 85→
 86→	// Points are ordered newest first, so checkpoint 1 is last
 87→	checkpoint1Point := points[2]
 88→	if checkpoint1Point.Message == "" {
 89→		t.Error("rewind point should have a message")
 90→	}
 91→
 92→	// Execute rewind to checkpoint 1
 93→	if err := env.Rewind(checkpoint1Point.ID); err != nil {
 94→		t.Fatalf("Rewind failed: %v", err)
 95→	}
 96→
 97→	// CORE ASSERTION: File contents restored
 98→	content = env.ReadFile("random.rb")
 99→	if content != rubyV1 {
100→		t.Errorf("after rewind: got %q, want %q", content, rubyV1)
101→	}
102→
103→	// CORE ASSERTION: Transcript available for resumption
104→	transcriptPath := filepath.Join(env.ClaudeProjectDir, session.ID+".jsonl")
105→	if _, err := os.Stat(transcriptPath); os.IsNotExist(err) {
106→		t.Errorf("transcript should be copied for claude -r, expected at %s", transcriptPath)
107→	}
108→}
