110→// TestTaskCheckpoint_RewindWorkflow tests rewind to task checkpoint (subagent completion).
111→// This verifies that:
112→// - Task checkpoints are created via PostToolUse[Task] hook
113→// - Task checkpoints appear as rewind points with IsTaskCheckpoint flag
114→// - Rewind to task checkpoint restores file state at that point
115→// - Transcript is available for session resumption
116→func TestTaskCheckpoint_RewindWorkflow(t *testing.T) {
117→	t.Parallel()
118→	env := NewFeatureBranchEnv(t)
119→	// Start a session
120→	session := env.NewSession()
121→	if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
122→		t.Fatalf("SimulateUserPromptSubmit failed: %v", err)
123→	}
124→
125→	// Build the transcript progressively
126→	session.TranscriptBuilder.AddUserMessage("Create some files using subagents")
127→	session.TranscriptBuilder.AddAssistantMessage("I'll use the Task tool to help.")
128→
129→	// === Task 1: Create first file ===
130→	task1ID := "toolu_task1_abc"
131→	task1AgentID := "agent_task1_xyz"
132→
133→	// Add Task tool use to transcript
134→	session.TranscriptBuilder.AddTaskToolUse(task1ID, "Create task1.txt")
135→	if err := session.TranscriptBuilder.WriteToFile(session.TranscriptPath); err != nil {
136→		t.Fatalf("failed to write transcript: %v", err)
137→	}
138→
139→	// Pre-task hook (before subagent runs)
140→	if err := env.SimulatePreTask(session.ID, session.TranscriptPath, task1ID); err != nil {
141→		t.Fatalf("SimulatePreTask task1 failed: %v", err)
142→	}
143→
144→	// Simulate subagent creating the file
145→	task1Content := "Created by task 1"
146→	env.WriteFile("task1.txt", task1Content)
147→
148→	// Create subagent transcript
149→	subagent1 := NewTranscriptBuilder()
150→	subagent1.AddUserMessage("Create task1.txt")
151→	toolID1 := subagent1.AddToolUse("mcp__acp__Write", "task1.txt", task1Content)
152→	subagent1.AddToolResult(toolID1)
153→	subagent1.AddAssistantMessage("Created task1.txt")
154→
155→	subagent1Path := filepath.Join(filepath.Dir(session.TranscriptPath), "agent-"+task1AgentID+".jsonl")
156→	if err := subagent1.WriteToFile(subagent1Path); err != nil {
157→		t.Fatalf("failed to write subagent1 transcript: %v", err)
158→	}
159→
160→	// Add task result to main transcript
161→	session.TranscriptBuilder.AddTaskToolResult(task1ID, task1AgentID)
162→	if err := session.TranscriptBuilder.WriteToFile(session.TranscriptPath); err != nil {
163→		t.Fatalf("failed to write transcript: %v", err)
164→	}
165→
166→	// Post-task hook (creates checkpoint)
167→	if err := env.SimulatePostTask(PostTaskInput{
168→		SessionID:      session.ID,
169→		TranscriptPath: session.TranscriptPath,
170→		ToolUseID:      task1ID,
171→		AgentID:        task1AgentID,
172→	}); err != nil {
173→		t.Fatalf("SimulatePostTask task1 failed: %v", err)
174→	}
175→
176→	// === Task 2: Create second file ===
177→	task2ID := "toolu_task2_def"
178→	task2AgentID := "agent_task2_uvw"
179→
180→	session.TranscriptBuilder.AddAssistantMessage("Now creating another file.")
181→	session.TranscriptBuilder.AddTaskToolUse(task2ID, "Create task2.txt")
182→	if err := session.TranscriptBuilder.WriteToFile(session.TranscriptPath); err != nil {
183→		t.Fatalf("failed to write transcript: %v", err)
184→	}
185→
186→	if err := env.SimulatePreTask(session.ID, session.TranscriptPath, task2ID); err != nil {
187→		t.Fatalf("SimulatePreTask task2 failed: %v", err)
188→	}
189→
190→	// Simulate subagent creating the second file
191→	task2Content := "Created by task 2"
192→	env.WriteFile("task2.txt", task2Content)
193→
194→	// Create subagent transcript
195→	subagent2 := NewTranscriptBuilder()
196→	subagent2.AddUserMessage("Create task2.txt")
197→	toolID2 := subagent2.AddToolUse("mcp__acp__Write", "task2.txt", task2Content)
198→	subagent2.AddToolResult(toolID2)
199→	subagent2.AddAssistantMessage("Created task2.txt")
200→
201→	subagent2Path := filepath.Join(filepath.Dir(session.TranscriptPath), "agent-"+task2AgentID+".jsonl")
202→	if err := subagent2.WriteToFile(subagent2Path); err != nil {
203→		t.Fatalf("failed to write subagent2 transcript: %v", err)
204→	}
205→
206→	// Add task result to main transcript
207→	session.TranscriptBuilder.AddTaskToolResult(task2ID, task2AgentID)
208→	if err := session.TranscriptBuilder.WriteToFile(session.TranscriptPath); err != nil {
209→		t.Fatalf("failed to write transcript: %v", err)
210→	}
211→
212→	// Post-task hook (creates checkpoint)
213→	if err := env.SimulatePostTask(PostTaskInput{
214→		SessionID:      session.ID,
215→		TranscriptPath: session.TranscriptPath,
216→		ToolUseID:      task2ID,
217→		AgentID:        task2AgentID,
218→	}); err != nil {
219→		t.Fatalf("SimulatePostTask task2 failed: %v", err)
220→	}
221→
222→	// End session
223→	session.TranscriptBuilder.AddAssistantMessage("All tasks complete!")
224→	if err := session.TranscriptBuilder.WriteToFile(session.TranscriptPath); err != nil {
225→		t.Fatalf("failed to write transcript: %v", err)
226→	}
227→
228→	if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
229→		t.Fatalf("SimulateStop failed: %v", err)
230→	}
231→
232→	// Verify both files exist
233→	if !env.FileExists("task1.txt") {
234→		t.Error("task1.txt should exist after session")
235→	}
236→	if !env.FileExists("task2.txt") {
237→		t.Error("task2.txt should exist after session")
238→	}
239→
240→	// Get rewind points
241→	points := env.GetRewindPoints()
242→
243→	// Filter to task checkpoints only
244→	taskPoints := filterTaskCheckpoints(points)
245→	if len(taskPoints) < 2 {
246→		t.Fatalf("expected at least 2 task checkpoints, got %d (total points: %d)", len(taskPoints), len(points))
247→	}
248→
249→	// Find task 1 checkpoint
250→	var task1Point *RewindPoint
251→	for i := range taskPoints {
