1160→// avoiding bloated session state from large ignored directories like node_modules/.
1161→// Returns paths relative to the repository root.
1162→func collectUntrackedFiles(ctx context.Context) ([]string, error) {
1163→	repoRoot, err := paths.WorktreeRoot(ctx)
1164→	if err != nil {
1165→		repoRoot = "."
1166→	}
1167→
1168→	cmd := exec.CommandContext(ctx, "git", "ls-files", "--others", "--exclude-standard", "-z")
1169→	cmd.Dir = repoRoot
1170→	output, err := cmd.Output()
1171→	if err != nil {
1172→		var exitErr *exec.ExitError
1173→		if errors.As(err, &exitErr) {
1174→			return nil, fmt.Errorf("git ls-files failed: %s: %w", strings.TrimSpace(string(exitErr.Stderr)), err)
1175→		}
1176→		return nil, fmt.Errorf("git ls-files failed: %w", err)
1177→	}
1178→
1179→	raw := string(output)
1180→	if raw == "" {
1181→		return nil, nil
1182→	}
1183→
1184→	var files []string
1185→	for _, f := range strings.Split(raw, "\x00") {
1186→		// Defense-in-depth: filter protected paths even though --exclude-standard should already handle them
1187→		if f != "" && !isProtectedPath(f) {
