520→// ListAllTemporaryCheckpoints lists checkpoint commits from ALL shadow branches.
521→// This is used for checkpoint lookup when the base commit is unknown (e.g., HEAD advanced since session start).
522→// The sessionID filter, if provided, limits results to commits from that session.
523→func (s *GitStore) ListAllTemporaryCheckpoints(ctx context.Context, sessionID string, limit int) ([]TemporaryCheckpointInfo, error) {
524→	if err := ctx.Err(); err != nil {
525→		return nil, err //nolint:wrapcheck // Propagating context cancellation
526→	}
527→
528→	// List all shadow branches
529→	branches, err := s.ListTemporary(ctx)
530→	if err != nil {
531→		return nil, fmt.Errorf("failed to list shadow branches: %w", err)
532→	}
533→
534→	var results []TemporaryCheckpointInfo
535→
536→	// Iterate through each shadow branch and collect checkpoints
537→	for _, branch := range branches {
538→		// Use the branch name directly to get checkpoints
539→		branchCheckpoints, branchErr := s.listCheckpointsForBranch(ctx, branch.BranchName, sessionID, limit)
540→		if branchErr != nil {
541→			if errors.Is(branchErr, context.Canceled) || errors.Is(branchErr, context.DeadlineExceeded) {
542→				return nil, branchErr
543→			}
544→			continue // Skip branches we can't read
545→		}
546→		results = append(results, branchCheckpoints...)
547→		if len(results) >= limit {
548→			results = results[:limit]
549→			break
550→		}
551→	}
552→
553→	return results, nil
554→}
