463→// PreviewRewind returns what will happen if rewinding to the given point.
464→// This allows showing warnings about untracked files that will be deleted.
465→func (s *ManualCommitStrategy) PreviewRewind(ctx context.Context, point RewindPoint) (*RewindPreview, error) {
466→	// Logs-only points don't modify the working directory
467→	if point.IsLogsOnly {
468→		return &RewindPreview{}, nil
469→	}
470→
471→	repo, err := OpenRepository(ctx)
472→	if err != nil {
473→		return nil, fmt.Errorf("failed to open git repository: %w", err)
474→	}
475→
476→	// Get the checkpoint commit
477→	commitHash := plumbing.NewHash(point.ID)
478→	commit, err := repo.CommitObject(commitHash)
479→	if err != nil {
480→		return nil, fmt.Errorf("failed to get commit: %w", err)
481→	}
482→
483→	tree, err := commit.Tree()
484→	if err != nil {
485→		return nil, fmt.Errorf("failed to get tree: %w", err)
486→	}
487→
488→	// Load session state to get untracked files that existed at session start
489→	sessionID, hasSessionTrailer := trailers.ParseSession(commit.Message)
490→	var preservedUntrackedFiles map[string]bool
491→	if hasSessionTrailer {
492→		state, stateErr := s.loadSessionState(ctx, sessionID)
493→		if stateErr == nil && state != nil && len(state.UntrackedFilesAtStart) > 0 {
494→			preservedUntrackedFiles = make(map[string]bool)
495→			for _, f := range state.UntrackedFilesAtStart {
496→				preservedUntrackedFiles[f] = true
497→			}
498→		}
499→	}
500→
501→	// Build set of files in the checkpoint tree (excluding metadata)
502→	checkpointFiles := make(map[string]bool)
503→	var filesToRestore []string
504→	err = tree.Files().ForEach(func(f *object.File) error {
505→		if err := ctx.Err(); err != nil {
506→			return err //nolint:wrapcheck // Propagating context cancellation
507→		}
508→		if !strings.HasPrefix(f.Name, entireDir) {
509→			checkpointFiles[f.Name] = true
510→			filesToRestore = append(filesToRestore, f.Name)
511→		}
512→		return nil
513→	})
514→	if err != nil {
515→		return nil, fmt.Errorf("failed to list checkpoint files: %w", err)
516→	}
517→
518→	// Get HEAD tree to identify tracked files
519→	head, err := repo.Head()
520→	if err != nil {
521→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
522→	}
523→	headCommit, err := repo.CommitObject(head.Hash())
524→	if err != nil {
525→		return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
526→	}
527→	headTree, err := headCommit.Tree()
528→	if err != nil {
529→		return nil, fmt.Errorf("failed to get HEAD tree: %w", err)
530→	}
531→
532→	// Build set of files tracked in HEAD
533→	trackedFiles := make(map[string]bool)
534→	//nolint:errcheck // Error is not critical for preview
535→	_ = headTree.Files().ForEach(func(f *object.File) error {
536→		if err := ctx.Err(); err != nil {
537→			return err //nolint:wrapcheck // Propagating context cancellation
538→		}
539→		trackedFiles[f.Name] = true
540→		return nil
541→	})
542→
543→	// Find untracked files that would be deleted.
544→	// Uses git ls-files to only consider non-ignored files.
545→	var filesToDelete []string
546→	untrackedNow, untrackedErr := collectUntrackedFiles(ctx)
547→	if untrackedErr != nil {
548→		fmt.Fprintf(os.Stderr, "Warning: could not list untracked files for preview: %v\n", untrackedErr)
549→		return &RewindPreview{
550→			FilesToRestore: filesToRestore,
551→			FilesToDelete:  filesToDelete,
552→		}, nil
553→	}
554→	for _, relPath := range untrackedNow {
555→		if checkpointFiles[relPath] {
556→			continue
557→		}
558→		if trackedFiles[relPath] {
559→			continue
560→		}
561→		if preservedUntrackedFiles[relPath] {
562→			continue
563→		}
564→		filesToDelete = append(filesToDelete, relPath)
565→	}
566→
567→	// Sort for consistent output
568→	sort.Strings(filesToRestore)
569→	sort.Strings(filesToDelete)
570→
571→	return &RewindPreview{
572→		FilesToRestore: filesToRestore,
573→		FilesToDelete:  filesToDelete,
574→	}, nil
575→}
