727→// ResolveAgentForRewind resolves the agent from checkpoint metadata.
728→func ResolveAgentForRewind(agentType types.AgentType) (agent.Agent, error) {
729→	ag, err := agent.GetByAgentType(agentType)
730→	if err != nil {
731→		return nil, fmt.Errorf("resolving agent %q: %w", agentType, err)
732→	}
733→	return ag, nil
734→}
