736→// readSessionPrompt reads the first prompt from the session's prompt.txt file stored in git.
737→// Returns an empty string if the prompt cannot be read.
738→func readSessionPrompt(repo *git.Repository, commitHash plumbing.Hash, metadataDir string) string {
739→	// Get the commit and its tree
740→	commit, err := repo.CommitObject(commitHash)
741→	if err != nil {
742→		return ""
743→	}
744→
745→	tree, err := commit.Tree()
746→	if err != nil {
747→		return ""
748→	}
749→
750→	// Look for prompt.txt in the metadata directory
751→	promptPath := metadataDir + "/" + paths.PromptFileName
752→	promptEntry, err := tree.File(promptPath)
753→	if err != nil {
754→		return ""
755→	}
756→
757→	content, err := promptEntry.Contents()
758→	if err != nil {
759→		return ""
760→	}
761→
762→	return ExtractFirstPrompt(content)
763→}
