765→// SessionRestoreStatus represents the status of a session being restored.
766→type SessionRestoreStatus int
767→
768→const (
769→	StatusNew             SessionRestoreStatus = iota // Local file doesn't exist
770→	StatusUnchanged                                   // Local and checkpoint are the same
771→	StatusCheckpointNewer                             // Checkpoint has newer entries
772→	StatusLocalNewer                                  // Local has newer entries (conflict)
773→)
774→
775→// SessionRestoreInfo contains information about a session being restored.
776→type SessionRestoreInfo struct {
777→	SessionID      string
778→	Prompt         string               // First prompt preview for display
779→	Status         SessionRestoreStatus // Status of this session
780→	LocalTime      time.Time
781→	CheckpointTime time.Time
782→}
783→
784→// classifySessionsForRestore checks all sessions in a checkpoint and returns info
785→// about each session, including whether local logs have newer timestamps.
786→// repoRoot is used to compute per-session agent directories.
787→// Sessions without agent metadata are skipped (cannot determine target directory).
788→func (s *ManualCommitStrategy) classifySessionsForRestore(ctx context.Context, repoRoot string, store cpkg.Store, checkpointID id.CheckpointID, summary *cpkg.CheckpointSummary) []SessionRestoreInfo {
789→	var sessions []SessionRestoreInfo
790→
791→	totalSessions := len(summary.Sessions)
792→	// Check all sessions (0-based indexing)
793→	for i := range totalSessions {
794→		content, err := store.ReadSessionContent(ctx, checkpointID, i)
795→		if err != nil || content == nil || len(content.Transcript) == 0 {
796→			continue
797→		}
798→
799→		sessionID := content.Metadata.SessionID
800→		if sessionID == "" || content.Metadata.Agent == "" {
801→			continue
802→		}
803→
804→		sessionAgent, agErr := ResolveAgentForRewind(content.Metadata.Agent)
805→		if agErr != nil {
806→			continue
807→		}
808→
809→		// Compute transcript path from current repo location for cross-machine portability.
810→		sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
811→		if dirErr != nil {
812→			continue
813→		}
814→		localPath := sessionAgent.ResolveSessionFile(sessionAgentDir, sessionID)
815→
816→		localTime := paths.GetLastTimestampFromFile(localPath)
817→		checkpointTime := paths.GetLastTimestampFromBytes(content.Transcript)
818→		status := ClassifyTimestamps(localTime, checkpointTime)
819→
820→		sessions = append(sessions, SessionRestoreInfo{
821→			SessionID:      sessionID,
822→			Prompt:         ExtractFirstPrompt(content.Prompts),
823→			Status:         status,
824→			LocalTime:      localTime,
825→			CheckpointTime: checkpointTime,
826→		})
827→	}
828→
829→	return sessions
830→}
831→
832→// ClassifyTimestamps determines the restore status based on local and checkpoint timestamps.
833→func ClassifyTimestamps(localTime, checkpointTime time.Time) SessionRestoreStatus {
834→	// Local file doesn't exist (no timestamp found)
835→	if localTime.IsZero() {
836→		return StatusNew
837→	}
838→
839→	// Can't determine checkpoint time - treat as new/safe
840→	if checkpointTime.IsZero() {
841→		return StatusNew
842→	}
843→
844→	// Compare timestamps
845→	if localTime.After(checkpointTime) {
846→		return StatusLocalNewer
847→	}
848→	if checkpointTime.After(localTime) {
849→		return StatusCheckpointNewer
850→	}
851→	return StatusUnchanged
852→}
853→
854→// StatusToText returns a human-readable status string.
855→func StatusToText(status SessionRestoreStatus) string {
856→	switch status {
857→	case StatusNew:
858→		return "(new)"
859→	case StatusUnchanged:
860→		return "(unchanged)"
861→	case StatusCheckpointNewer:
862→		return "(checkpoint is newer)"
863→	case StatusLocalNewer:
864→		return "(local is newer)" // shouldn't appear in non-conflict list
865→	default:
866→		return ""
867→	}
868→}
869→
870→// PromptOverwriteNewerLogs asks the user for confirmation to overwrite local
871→// session logs that have newer timestamps than the checkpoint versions.
872→func PromptOverwriteNewerLogs(sessions []SessionRestoreInfo) (bool, error) {
873→	// Separate conflicting and non-conflicting sessions
874→	var conflicting, nonConflicting []SessionRestoreInfo
875→	for _, s := range sessions {
876→		if s.Status == StatusLocalNewer {
877→			conflicting = append(conflicting, s)
878→		} else {
879→			nonConflicting = append(nonConflicting, s)
880→		}
881→	}
882→
883→	fmt.Fprintf(os.Stderr, "\nWarning: Local session log(s) have newer entries than the checkpoint:\n")
884→	for _, info := range conflicting {
885→		// Show prompt if available, otherwise fall back to session ID
886→		if info.Prompt != "" {
887→			fmt.Fprintf(os.Stderr, "  \"%s\"\n", info.Prompt)
888→		} else {
889→			fmt.Fprintf(os.Stderr, "  Session: %s\n", info.SessionID)
890→		}
891→		fmt.Fprintf(os.Stderr, "    Local last entry:      %s\n", info.LocalTime.Local().Format("2006-01-02 15:04:05"))
892→		fmt.Fprintf(os.Stderr, "    Checkpoint last entry: %s\n", info.CheckpointTime.Local().Format("2006-01-02 15:04:05"))
893→	}
894→
895→	// Show non-conflicting sessions with their status
896→	if len(nonConflicting) > 0 {
897→		fmt.Fprintf(os.Stderr, "\nThese other session(s) will also be restored:\n")
898→		for _, info := range nonConflicting {
899→			statusText := StatusToText(info.Status)
900→			if info.Prompt != "" {
901→				fmt.Fprintf(os.Stderr, "  \"%s\" %s\n", info.Prompt, statusText)
902→			} else {
903→				fmt.Fprintf(os.Stderr, "  Session: %s %s\n", info.SessionID, statusText)
904→			}
905→		}
906→	}
907→
908→	fmt.Fprintf(os.Stderr, "\nOverwriting will lose the newer local entries.\n\n")
909→
910→	var confirmed bool
911→	form := huh.NewForm(
912→		huh.NewGroup(
913→			huh.NewConfirm().
914→				Title("Overwrite local session logs with checkpoint versions?").
915→				Value(&confirmed),
916→		),
917→	)
918→	if isAccessibleMode() {
919→		form = form.WithAccessible(true)
920→	}
921→
922→	if err := form.Run(); err != nil {
923→		if errors.Is(err, huh.ErrUserAborted) {
924→			return false, nil
925→		}
926→		return false, fmt.Errorf("failed to get confirmation: %w", err)
927→	}
928→
929→	return confirmed, nil
930→}
