 38→// MaxCommitTraversalDepth is the safety limit for walking git commit history.
 39→// Prevents unbounded traversal in repositories with very long histories.
 40→const MaxCommitTraversalDepth = 1000
 41→
 42→// errStop is a sentinel error used to break out of git log iteration.
 43→// Shared across strategies that iterate through git commits.
 44→// NOTE: A similar sentinel exists in checkpoint/temporary.go - this is intentional.
 45→// Each package needs its own package-scoped sentinel for git log iteration patterns.
 46→var errStop = errors.New("stop iteration")
