 48→// IsEmptyRepository returns true if the repository has no commits yet.
 49→// After git-init, HEAD points to an unborn branch (e.g., refs/heads/main)
 50→// whose target does not yet exist. repo.Head() returns ErrReferenceNotFound
 51→// in this case.
 52→func IsEmptyRepository(repo *git.Repository) bool {
 53→	_, err := repo.Head()
 54→	return errors.Is(err, plumbing.ErrReferenceNotFound)
