 57→// EnsureSetup ensures the strategy is properly set up.
 58→func EnsureSetup(ctx context.Context) error {
 59→	if err := EnsureEntireGitignore(ctx); err != nil {
 60→		return err
 61→	}
 62→
 63→	// Ensure the entire/checkpoints/v1 orphan branch exists for permanent session storage
 64→	repo, err := OpenRepository(ctx)
 65→	if err != nil {
 66→		return fmt.Errorf("failed to open git repository: %w", err)
 67→	}
 68→	if err := EnsureMetadataBranch(repo); err != nil {
 69→		return fmt.Errorf("failed to ensure metadata branch: %w", err)
 70→	}
 71→
 72→	// Install generic hooks (they delegate to strategy at runtime)
 73→	if !IsGitHookInstalled(ctx) {
 74→		localDev, absoluteHookPath := hookSettingsFromConfig(ctx)
 75→		if _, err := InstallGitHook(ctx, true, localDev, absoluteHookPath); err != nil {
 76→			return fmt.Errorf("failed to install git hooks: %w", err)
 77→		}
 78→	}
 79→	return nil
 80→}
