 82→// IsAncestorOf checks if commit is an ancestor of (or equal to) target.
 83→// Returns true if target can reach commit by following parent links.
 84→// Limits search to MaxCommitTraversalDepth commits to avoid excessive traversal.
 85→func IsAncestorOf(ctx context.Context, repo *git.Repository, commit, target plumbing.Hash) bool {
 86→	if commit == target {
 87→		return true
 88→	}
 89→
 90→	iter, err := repo.Log(&git.LogOptions{From: target})
 91→	if err != nil {
 92→		return false
 93→	}
 94→	defer iter.Close()
 95→
 96→	found := false
 97→	count := 0
 98→	_ = iter.ForEach(func(c *object.Commit) error { //nolint:errcheck // Best-effort search, errors are non-fatal
 99→		if err := ctx.Err(); err != nil {
100→			return err //nolint:wrapcheck // Propagating context cancellation
101→		}
102→		count++
103→		if count > MaxCommitTraversalDepth {
104→			return errStop
105→		}
106→		if c.Hash == commit {
107→			found = true
108→			return errStop
109→		}
110→		return nil
111→	})
112→
113→	return found
114→}
