116→// ListCheckpoints returns all checkpoints from the entire/checkpoints/v1 branch.
117→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
118→func ListCheckpoints(ctx context.Context) ([]CheckpointInfo, error) {
119→	repo, err := OpenRepository(ctx)
120→	if err != nil {
121→		return nil, fmt.Errorf("failed to open git repository: %w", err)
122→	}
123→
124→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
125→	ref, err := repo.Reference(refName, true)
126→	if err != nil {
127→		//nolint:nilerr // No sessions branch yet is expected, return empty list
128→		return []CheckpointInfo{}, nil
129→	}
130→
131→	commit, err := repo.CommitObject(ref.Hash())
132→	if err != nil {
133→		return nil, fmt.Errorf("failed to get commit object: %w", err)
134→	}
135→
136→	tree, err := commit.Tree()
137→	if err != nil {
138→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
139→	}
140→
141→	var checkpoints []CheckpointInfo
142→
143→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
144→	// The tree has 2-character directories (hex buckets)
145→	for _, bucketEntry := range tree.Entries {
146→		if bucketEntry.Mode != filemode.Dir {
147→			continue
148→		}
149→		// Bucket should be 2 hex chars
150→		if len(bucketEntry.Name) != 2 {
151→			continue
152→		}
153→
154→		bucketTree, treeErr := repo.TreeObject(bucketEntry.Hash)
155→		if treeErr != nil {
156→			continue
157→		}
158→
159→		// Each entry in the bucket is the remaining part of the checkpoint ID
160→		for _, checkpointEntry := range bucketTree.Entries {
161→			if checkpointEntry.Mode != filemode.Dir {
162→				continue
163→			}
164→
165→			checkpointTree, cpTreeErr := repo.TreeObject(checkpointEntry.Hash)
166→			if cpTreeErr != nil {
167→				continue
168→			}
169→
170→			// Reconstruct checkpoint ID: <bucket><remaining>
171→			checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
172→			checkpointID, cpErr := id.NewCheckpointID(checkpointIDStr)
173→			if cpErr != nil {
174→				// Skip invalid checkpoint IDs
175→				continue
176→			}
177→
178→			info := CheckpointInfo{
179→				CheckpointID: checkpointID,
180→			}
181→
182→			// Get details from metadata file (CheckpointSummary format)
183→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
184→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
185→					var summary checkpoint.CheckpointSummary
186→					if json.Unmarshal([]byte(content), &summary) == nil && len(summary.Sessions) > 0 {
187→						info.CheckpointsCount = summary.CheckpointsCount
188→						info.FilesTouched = summary.FilesTouched
189→						info.SessionCount = len(summary.Sessions)
190→
191→						// Read session-level metadata for Agent, SessionID, CreatedAt, SessionIDs
192→						for i, sessionPaths := range summary.Sessions {
193→							if sessionPaths.Metadata != "" {
194→								// SessionFilePaths now contains absolute paths with leading "/"
195→								// Strip the leading "/" for tree.File() which expects paths without leading slash
196→								sessionMetadataPath := strings.TrimPrefix(sessionPaths.Metadata, "/")
197→								if sessionFile, sErr := tree.File(sessionMetadataPath); sErr == nil {
198→									if sessionContent, scErr := sessionFile.Contents(); scErr == nil {
199→										var sessionMetadata checkpoint.CommittedMetadata
200→										if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
201→											info.SessionIDs = append(info.SessionIDs, sessionMetadata.SessionID)
202→											// Use first session's metadata for Agent, SessionID, CreatedAt
203→											if i == 0 {
204→												info.Agent = sessionMetadata.Agent
205→												info.SessionID = sessionMetadata.SessionID
206→												info.CreatedAt = sessionMetadata.CreatedAt
207→												info.IsTask = sessionMetadata.IsTask
208→												info.ToolUseID = sessionMetadata.ToolUseID
209→											}
210→										}
211→									}
212→								}
213→							}
214→						}
215→					}
216→				}
217→			}
218→
219→			checkpoints = append(checkpoints, info)
220→		}
221→	}
222→
223→	// Sort by time (most recent first)
224→	sort.Slice(checkpoints, func(i, j int) bool {
225→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
226→	})
227→
228→	return checkpoints, nil
229→}
