282→// EnsureMetadataBranch creates the local entire/checkpoints/v1 branch if it doesn't exist.
283→// If the remote-tracking branch (origin/entire/checkpoints/v1) exists, creates the local
284→// branch from it to preserve existing checkpoint data. Otherwise creates an empty orphan.
285→func EnsureMetadataBranch(repo *git.Repository) error {
286→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
287→
288→	// Check if local branch already exists
289→	_, err := repo.Reference(refName, true)
290→	if err == nil {
291→		return nil
292→	}
293→	if !errors.Is(err, plumbing.ErrReferenceNotFound) {
294→		return fmt.Errorf("failed to check metadata branch: %w", err)
295→	}
296→
297→	// Local branch doesn't exist — create from remote if available
298→	remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
299→	remoteRef, remoteErr := repo.Reference(remoteRefName, true)
300→	if remoteErr != nil && !errors.Is(remoteErr, plumbing.ErrReferenceNotFound) {
301→		return fmt.Errorf("failed to check remote metadata branch: %w", remoteErr)
302→	}
303→	if remoteErr == nil {
304→		ref := plumbing.NewHashReference(refName, remoteRef.Hash())
305→		if err := repo.Storer.SetReference(ref); err != nil {
306→			return fmt.Errorf("failed to create metadata branch from remote: %w", err)
307→		}
308→		fmt.Fprintf(os.Stderr, "✓ Created local branch '%s' from origin\n", paths.MetadataBranchName)
309→		return nil
310→	}
311→
312→	// No local or remote branch — create empty orphan
313→	emptyTree := &object.Tree{Entries: []object.TreeEntry{}}
314→	obj := repo.Storer.NewEncodedObject()
315→	if err := emptyTree.Encode(obj); err != nil {
316→		return fmt.Errorf("failed to encode empty tree: %w", err)
317→	}
318→	emptyTreeHash, err := repo.Storer.SetEncodedObject(obj)
319→	if err != nil {
320→		return fmt.Errorf("failed to store empty tree: %w", err)
321→	}
322→
323→	// Create orphan commit (no parent)
324→	now := time.Now()
325→	authorName, authorEmail := GetGitAuthorFromRepo(repo)
326→	sig := object.Signature{
327→		Name:  authorName,
328→		Email: authorEmail,
329→		When:  now,
330→	}
331→
332→	commit := &object.Commit{
333→		TreeHash:  emptyTreeHash,
334→		Author:    sig,
335→		Committer: sig,
336→		Message:   "Initialize metadata branch\n\nThis branch stores session metadata.\n",
337→	}
338→	// Note: No ParentHashes - this is an orphan commit
339→
340→	commitObj := repo.Storer.NewEncodedObject()
341→	if err := commit.Encode(commitObj); err != nil {
342→		return fmt.Errorf("failed to encode orphan commit: %w", err)
343→	}
344→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
345→	if err != nil {
346→		return fmt.Errorf("failed to store orphan commit: %w", err)
347→	}
348→
349→	// Create branch reference
350→	ref := plumbing.NewHashReference(refName, commitHash)
351→	if err := repo.Storer.SetReference(ref); err != nil {
352→		return fmt.Errorf("failed to create metadata branch: %w", err)
353→	}
354→
355→	fmt.Fprintf(os.Stderr, "✓ Created orphan branch '%s' for session metadata\n", paths.MetadataBranchName)
356→	return nil
357→}
