447→// ExtractFirstPrompt extracts and truncates the first meaningful prompt from prompt content.
448→// Prompts are separated by "\n\n---\n\n". Skips empty prompts and separator-only content.
449→// Returns empty string if no valid prompt is found.
450→func ExtractFirstPrompt(content string) string {
451→	if content == "" {
452→		return ""
453→	}
454→
455→	// Prompts are separated by "\n\n---\n\n"
456→	// Find the first non-empty prompt
457→	prompts := strings.Split(content, "\n\n---\n\n")
458→	var firstPrompt string
459→	for _, p := range prompts {
460→		cleaned := strings.TrimSpace(p)
461→		// Skip empty prompts or prompts that are just dashes/separators
462→		if cleaned == "" || isOnlySeparators(cleaned) {
463→			continue
464→		}
465→		firstPrompt = cleaned
466→		break
467→	}
468→
469→	if firstPrompt == "" {
470→		return ""
471→	}
472→
473→	return TruncateDescription(firstPrompt, MaxDescriptionLength)
474→}
