253→// Rewind restores the working directory to a checkpoint.
254→//
255→
256→func (s *ManualCommitStrategy) Rewind(ctx context.Context, point RewindPoint) error {
257→	repo, err := OpenRepository(ctx)
258→	if err != nil {
259→		return fmt.Errorf("failed to open git repository: %w", err)
260→	}
261→
262→	// Get the checkpoint commit
263→	commitHash := plumbing.NewHash(point.ID)
264→	commit, err := repo.CommitObject(commitHash)
265→	if err != nil {
266→		return fmt.Errorf("failed to get commit: %w", err)
267→	}
268→
269→	tree, err := commit.Tree()
270→	if err != nil {
271→		return fmt.Errorf("failed to get tree: %w", err)
272→	}
273→
274→	// Reset the shadow branch to the rewound checkpoint
275→	// This ensures the next checkpoint will only include prompts from this point forward
276→	if err := s.resetShadowBranchToCheckpoint(ctx, repo, commit); err != nil {
277→		// Log warning but don't fail - file restoration is the primary operation
278→		fmt.Fprintf(os.Stderr, "[entire] Warning: failed to reset shadow branch: %v\n", err)
279→	}
280→
281→	// Load session state to get untracked files that existed at session start
282→	sessionID, hasSessionTrailer := trailers.ParseSession(commit.Message)
283→	var preservedUntrackedFiles map[string]bool
284→	if hasSessionTrailer {
285→		state, stateErr := s.loadSessionState(ctx, sessionID)
286→		if stateErr == nil && state != nil && len(state.UntrackedFilesAtStart) > 0 {
287→			preservedUntrackedFiles = make(map[string]bool)
288→			for _, f := range state.UntrackedFilesAtStart {
289→				preservedUntrackedFiles[f] = true
290→			}
291→		}
292→	}
293→
294→	// Build set of files in the checkpoint tree (excluding metadata)
295→	checkpointFiles := make(map[string]bool)
296→	err = tree.Files().ForEach(func(f *object.File) error {
297→		if err := ctx.Err(); err != nil {
298→			return err //nolint:wrapcheck // Propagating context cancellation
299→		}
300→		if !strings.HasPrefix(f.Name, entireDir) {
301→			checkpointFiles[f.Name] = true
302→		}
303→		return nil
304→	})
305→	if err != nil {
306→		return fmt.Errorf("failed to list checkpoint files: %w", err)
307→	}
308→
309→	// Get HEAD tree to identify tracked files
310→	head, err := repo.Head()
311→	if err != nil {
312→		return fmt.Errorf("failed to get HEAD: %w", err)
313→	}
314→	headCommit, err := repo.CommitObject(head.Hash())
315→	if err != nil {
316→		return fmt.Errorf("failed to get HEAD commit: %w", err)
317→	}
318→	headTree, err := headCommit.Tree()
319→	if err != nil {
320→		return fmt.Errorf("failed to get HEAD tree: %w", err)
321→	}
322→
323→	// Build set of files tracked in HEAD
324→	trackedFiles := make(map[string]bool)
325→	//nolint:errcheck // Error is not critical for rewind
326→	_ = headTree.Files().ForEach(func(f *object.File) error {
327→		if err := ctx.Err(); err != nil {
328→			return err //nolint:wrapcheck // Propagating context cancellation
329→		}
330→		trackedFiles[f.Name] = true
331→		return nil
332→	})
333→
334→	// Get repository root to walk from there
335→	repoRoot, err := paths.WorktreeRoot(ctx)
336→	if err != nil {
337→		repoRoot = "." // Fallback to current directory
338→	}
339→
340→	// Find and delete untracked files that aren't in the checkpoint.
341→	// Uses git ls-files to only consider non-ignored files, avoiding walks through
342→	// large ignored directories like node_modules/.
343→	untrackedNow, err := collectUntrackedFiles(ctx)
344→	if err != nil {
345→		// Non-fatal - continue with restoration
346→		fmt.Fprintf(os.Stderr, "Warning: error listing untracked files: %v\n", err)
347→	}
348→	for _, relPath := range untrackedNow {
349→		// If file is in checkpoint, it will be restored
350→		if checkpointFiles[relPath] {
351→			continue
352→		}
353→
354→		// If file is tracked in HEAD, don't delete (user's committed work)
355→		if trackedFiles[relPath] {
356→			continue
357→		}
358→
359→		// If file existed at session start, preserve it (untracked user files)
360→		if preservedUntrackedFiles[relPath] {
361→			continue
362→		}
363→
364→		// File is untracked and not in checkpoint - delete it
365→		absPath := filepath.Join(repoRoot, relPath)
366→		if removeErr := os.Remove(absPath); removeErr == nil {
367→			fmt.Fprintf(os.Stderr, "  Deleted: %s\n", relPath)
368→		}
369→	}
370→
371→	// Restore files from checkpoint
372→	err = tree.Files().ForEach(func(f *object.File) error {
373→		if err := ctx.Err(); err != nil {
374→			return err //nolint:wrapcheck // Propagating context cancellation
375→		}
376→		// Skip metadata directories - these are for checkpoint storage, not working dir
377→		if strings.HasPrefix(f.Name, entireDir) {
378→			return nil
379→		}
380→
381→		contents, err := f.Contents()
382→		if err != nil {
383→			return fmt.Errorf("failed to read file %s: %w", f.Name, err)
384→		}
385→
386→		// Ensure directory exists
387→		dir := filepath.Dir(f.Name)
388→		if dir != "." {
389→			//nolint:gosec // G301: Need 0o755 for user directories during rewind
390→			if err := os.MkdirAll(dir, 0o755); err != nil {
391→				return fmt.Errorf("failed to create directory %s: %w", dir, err)
392→			}
393→		}
394→
395→		// Write file with appropriate permissions
396→		var perm os.FileMode = 0o644
397→		if f.Mode == filemode.Executable {
398→			perm = 0o755
399→		}
400→		if err := os.WriteFile(f.Name, []byte(contents), perm); err != nil {
401→			return fmt.Errorf("failed to write file %s: %w", f.Name, err)
402→		}
403→
404→		fmt.Fprintf(os.Stderr, "  Restored: %s\n", f.Name)
405→		return nil
406→	})
407→	if err != nil {
408→		return fmt.Errorf("failed to iterate tree files: %w", err)
409→	}
410→
411→	fmt.Println()
412→	if len(point.ID) >= 7 {
413→		fmt.Printf("Restored files from shadow commit %s\n", point.ID[:7])
414→	} else {
415→		fmt.Printf("Restored files from shadow commit %s\n", point.ID)
416→	}
417→	fmt.Println()
418→
419→	return nil
420→}
