441→// TestResolveLatestCheckpoint verifies that resolveLatestCheckpoint returns the
442→// checkpoint with the newest CreatedAt, regardless of trailer order.
443→func TestResolveLatestCheckpoint(t *testing.T) {
444→	tmpDir := t.TempDir()
445→	t.Chdir(tmpDir)
446→
447→	repo, _, _ := setupResumeTestRepo(t, tmpDir, false)
448→
449→	// Create checkpoints with different timestamps.
450→	// Simulate git CLI squash merge order: newest first in the commit message.
451→	t1 := time.Date(2025, 1, 1, 10, 0, 0, 0, time.UTC) // oldest
452→	t2 := time.Date(2025, 1, 1, 11, 0, 0, 0, time.UTC)
453→	t3 := time.Date(2025, 1, 1, 12, 0, 0, 0, time.UTC) // newest
454→
455→	cpID1 := createCheckpointOnMetadataBranchFull(t, repo, "session-oldest", id.MustCheckpointID("aaa111bbb222"), t1)
456→	cpID2 := createCheckpointOnMetadataBranchFull(t, repo, "session-middle", id.MustCheckpointID("ccc333ddd444"), t2)
457→	cpID3 := createCheckpointOnMetadataBranchFull(t, repo, "session-newest", id.MustCheckpointID("eee555fff666"), t3)
458→
459→	// Pass checkpoint IDs in reverse chronological order (newest first),
460→	// simulating git CLI squash merge trailer order.
461→	reverseOrderIDs := []id.CheckpointID{cpID3, cpID2, cpID1}
462→	latest, tree, err := resolveLatestCheckpoint(context.Background(), repo, reverseOrderIDs)
463→	if err != nil {
464→		t.Fatalf("resolveLatestCheckpoint() error = %v", err)
465→	}
466→
467→	// Should return the newest checkpoint regardless of input order
468→	if latest.String() != cpID3.String() {
469→		t.Errorf("resolveLatestCheckpoint() = %s, want newest %s", latest, cpID3)
470→	}
471→
472→	// Should return a non-nil tree for reuse
473→	if tree == nil {
474→		t.Error("resolveLatestCheckpoint() returned nil tree")
475→	}
476→
477→	// Also verify with chronological order
478→	chronologicalIDs := []id.CheckpointID{cpID1, cpID2, cpID3}
479→	latest2, _, err := resolveLatestCheckpoint(context.Background(), repo, chronologicalIDs)
480→	if err != nil {
481→		t.Fatalf("resolveLatestCheckpoint() error = %v", err)
482→	}
483→	if latest2.String() != cpID3.String() {
484→		t.Errorf("resolveLatestCheckpoint() = %s, want newest %s", latest2, cpID3)
485→	}
486→}
