744→	} else {
745→		var silentErr *SilentError
746→		if !errors.As(err, &silentErr) {
747→			t.Errorf("resumeFromCurrentBranch() should return SilentError, got: %v", err)
748→		}
749→	}
750→}
751→

350→	ref := plumbing.NewHashReference(refName, commitHash)
351→	if err := repo.Storer.SetReference(ref); err != nil {
352→		return fmt.Errorf("failed to create metadata branch: %w", err)
353→	}
354→
355→	fmt.Fprintf(os.Stderr, "✓ Created orphan branch '%s' for session metadata\n", paths.MetadataBranchName)
356→	return nil
357→}
