476→// ReadSessionPromptFromTree reads the first meaningful prompt from a checkpoint's prompt.txt file in a git tree.
477→// Returns an empty string if the prompt cannot be read.
478→func ReadSessionPromptFromTree(tree *object.Tree, checkpointPath string) string {
479→	promptPath := checkpointPath + "/" + paths.PromptFileName
480→	file, err := tree.File(promptPath)
481→	if err != nil {
482→		return ""
483→	}
484→
485→	content, err := file.Contents()
486→	if err != nil {
487→		return ""
488→	}
489→
490→	return ExtractFirstPrompt(content)
491→}
