493→// ReadAgentTypeFromTree reads the agent type from a checkpoint's metadata.json file in a git tree.
494→// If metadata.json doesn't exist (shadow branches), it falls back to detecting the agent
495→// from the presence of agent-specific config files (.gemini/settings.json or .claude/).
496→// Returns agent.AgentTypeUnknown if the agent type cannot be determined.
497→func ReadAgentTypeFromTree(tree *object.Tree, checkpointPath string) types.AgentType {
498→	// First, try to read from metadata.json (present in condensed/committed checkpoints)
499→	metadataPath := checkpointPath + "/" + paths.MetadataFileName
500→	if file, err := tree.File(metadataPath); err == nil {
501→		if content, err := file.Contents(); err == nil {
502→			var metadata checkpoint.CommittedMetadata
503→			if err := json.Unmarshal([]byte(content), &metadata); err == nil && metadata.Agent != "" {
504→				return metadata.Agent
505→			}
506→		}
507→	}
508→
509→	// Fall back to detecting agent from config files (shadow branches don't have metadata.json).
510→	// Order: Gemini (most specific check), Claude (established default), OpenCode (newest/preview).
511→	if _, err := tree.File(".gemini/settings.json"); err == nil {
512→		return agent.AgentTypeGemini
513→	}
514→	if _, err := tree.Tree(".claude"); err == nil {
515→		return agent.AgentTypeClaudeCode
516→	}
517→	// OpenCode: .opencode directory or opencode.json config
518→	if _, err := tree.Tree(".opencode"); err == nil {
519→		return agent.AgentTypeOpenCode
520→	}
521→	if _, err := tree.File("opencode.json"); err == nil {
522→		return agent.AgentTypeOpenCode
523→	}
524→
525→	return agent.AgentTypeUnknown
526→}
