528→// isOnlySeparators checks if a string contains only dashes, spaces, and newlines.
529→func isOnlySeparators(s string) bool {
530→	for _, r := range s {
531→		if r != '-' && r != ' ' && r != '\n' && r != '\r' && r != '\t' {
532→			return false
533→		}
534→	}
535→	return true
536→}
