538→// ReadLatestSessionPromptFromCommittedTree reads the first prompt from a committed checkpoint's
539→// latest session on the metadata branch tree. This navigates the sharded directory layout:
540→// <cpID.Path()>/<latestSessionIndex>/prompt.txt
541→//
542→// This is an O(1) tree lookup that avoids reading the full transcript.
543→// sessionCount is the number of sessions in the checkpoint (from CommittedInfo.SessionCount).
544→func ReadLatestSessionPromptFromCommittedTree(tree *object.Tree, cpID id.CheckpointID, sessionCount int) string {
545→	cpPath := cpID.Path()
546→	cpTree, err := tree.Tree(cpPath)
547→	if err != nil {
548→		return ""
549→	}
550→
551→	// Find the latest session subdirectory.
552→	// Sessions use 0-based indexing: 0/, 1/, 2/, etc.
553→	latestIndex := sessionCount - 1
554→	if latestIndex < 0 {
555→		latestIndex = 0
556→	}
557→	sessionPath := strconv.Itoa(latestIndex)
558→	sessionTree, err := cpTree.Tree(sessionPath)
559→	if err != nil {
560→		// Fall back to session 0 if the computed index doesn't exist
561→		sessionTree, err = cpTree.Tree("0")
562→		if err != nil {
563→			return ""
564→		}
565→	}
566→
567→	file, err := sessionTree.File(paths.PromptFileName)
568→	if err != nil {
569→		return ""
570→	}
571→
572→	content, err := file.Contents()
573→	if err != nil {
574→		return ""
575→	}
576→
577→	return ExtractFirstPrompt(content)
578→}
579→
580→// ReadAllSessionPromptsFromTree reads the first prompt for all sessions in a multi-session checkpoint.
581→// Returns a slice of prompts parallel to sessionIDs (oldest to newest).
582→// For single-session checkpoints, returns a slice with just the root prompt.
583→func ReadAllSessionPromptsFromTree(tree *object.Tree, checkpointPath string, sessionCount int, sessionIDs []string) []string {
584→	if sessionCount <= 1 || len(sessionIDs) <= 1 {
585→		// Single session - just return the root prompt
586→		prompt := ReadSessionPromptFromTree(tree, checkpointPath)
587→		if prompt != "" {
588→			return []string{prompt}
589→		}
590→		return nil
591→	}
592→
593→	// Multi-session: read prompts from archived folders (0/, 1/, etc.) and root
594→	prompts := make([]string, len(sessionIDs))
595→
596→	// Read archived session prompts (folders 0, 1, ... N-2)
597→	for i := range sessionCount - 1 {
598→		archivedPath := fmt.Sprintf("%s/%d", checkpointPath, i)
599→		prompts[i] = ReadSessionPromptFromTree(tree, archivedPath)
600→	}
601→
602→	// Read the most recent session prompt (at root level)
603→	prompts[len(prompts)-1] = ReadSessionPromptFromTree(tree, checkpointPath)
604→
605→	return prompts
606→}
