628→// OpenRepository opens the git repository with linked worktree support enabled.
629→// It uses git.PlainOpenWithOptions with EnableDotGitCommonDir set to true,
630→// which is required for proper operation in git worktrees created via 'git worktree add'.
631→//
632→// Without EnableDotGitCommonDir, go-git operations in worktrees can silently fail:
633→// - Commits appear to succeed but are not persisted
634→// - Refs are written to incorrect locations
635→// - The worktree's HEAD/index don't get updated properly
636→//
637→// This happens because worktrees use .git as a file (pointing to the main repo)
638→// rather than a directory, and go-git needs to route paths correctly between
639→// shared (.git/) and per-worktree (.git/worktrees/<name>/) locations.
640→//
641→// The function first uses 'git rev-parse --show-toplevel' to find the repository
642→// root, which works correctly even when called from a subdirectory within the repo.
643→func OpenRepository(ctx context.Context) (*git.Repository, error) {
644→	repoRoot, err := paths.WorktreeRoot(ctx)
645→	if err != nil {
646→		// Fallback to current directory if git command fails
647→		// (e.g., if git is not installed or we're not in a repo)
648→		repoRoot = "."
649→	}

127→// GetLogsOnlyRewindPoints finds commits in the current branch's history that have
128→// condensed session logs on the entire/checkpoints/v1 branch. These are commits that
129→// were created with session data but the shadow branch has been condensed.
130→//
131→// The function works by:
132→// 1. Getting all checkpoints from the entire/checkpoints/v1 branch
133→// 2. Building a map of checkpoint ID -> checkpoint info
134→// 3. Scanning the current branch history for commits with Entire-Checkpoint trailers
135→// 4. Matching by checkpoint ID (stable across amend/rebase)
136→func (s *ManualCommitStrategy) GetLogsOnlyRewindPoints(ctx context.Context, limit int) ([]RewindPoint, error) {
137→	repo, err := OpenRepository(ctx)
138→	if err != nil {
139→		return nil, err
140→	}
141→
142→	// Get all checkpoints from entire/checkpoints/v1 branch
143→	checkpoints, err := s.listCheckpoints(ctx)
144→	if err != nil {
145→		// No checkpoints yet is fine
146→		return nil, nil //nolint:nilerr // Expected when no checkpoints exist
147→	}
148→
149→	if len(checkpoints) == 0 {
150→		return nil, nil
151→	}
152→
153→	// Build map of checkpoint ID -> checkpoint info
154→	// Checkpoint ID is the stable link from Entire-Checkpoint trailer
155→	checkpointInfoMap := make(map[id.CheckpointID]CheckpointInfo)
156→	for _, cp := range checkpoints {
157→		if !cp.CheckpointID.IsEmpty() {
158→			checkpointInfoMap[cp.CheckpointID] = cp
159→		}
160→	}
161→
162→	// Get metadata branch tree for reading session prompts (best-effort, ignore errors)
163→	metadataTree, _ := GetMetadataBranchTree(repo) //nolint:errcheck // Best-effort for session prompts
164→
165→	head, err := repo.Head()
166→	if err != nil {
167→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
168→	}
169→
170→	// Use LogOptions with Order=LogOrderCommitterTime to traverse all parents of merge commits.
171→	iter, err := repo.Log(&git.LogOptions{
172→		From:  head.Hash(),
173→		Order: git.LogOrderCommitterTime,
174→	})
175→	if err != nil {
176→		return nil, fmt.Errorf("failed to get commit log: %w", err)
177→	}
178→
179→	var points []RewindPoint
180→	count := 0
181→
182→	err = iter.ForEach(func(c *object.Commit) error {
183→		if err := ctx.Err(); err != nil {
184→			return err //nolint:wrapcheck // Propagating context cancellation
185→		}
186→		if count >= logsOnlyScanLimit {
187→			return errStop
188→		}
189→		count++
190→
191→		// Extract checkpoint ID from Entire-Checkpoint trailer (ParseCheckpoint validates format)
192→		cpID, found := trailers.ParseCheckpoint(c.Message)
193→		if !found {
194→			return nil
195→		}
196→		// Check if this checkpoint ID has metadata on entire/checkpoints/v1
197→		cpInfo, found := checkpointInfoMap[cpID]
198→		if !found {
199→			return nil
200→		}
201→
202→		// Create logs-only rewind point
203→		message := strings.Split(c.Message, "\n")[0]
204→
205→		// Read session prompts from metadata tree
206→		var sessionPrompt string
207→		var sessionPrompts []string
208→		if metadataTree != nil {
209→			checkpointPath := paths.CheckpointPath(cpInfo.CheckpointID) //nolint:staticcheck // already present in codebase
210→			// For multi-session checkpoints, read all prompts
211→			if cpInfo.SessionCount > 1 && len(cpInfo.SessionIDs) > 1 {
212→				sessionPrompts = ReadAllSessionPromptsFromTree(metadataTree, checkpointPath, cpInfo.SessionCount, cpInfo.SessionIDs)
213→				// Use the last (most recent) prompt as the main session prompt
214→				if len(sessionPrompts) > 0 {
215→					sessionPrompt = sessionPrompts[len(sessionPrompts)-1]
216→				}
217→			} else {
218→				sessionPrompt = ReadSessionPromptFromTree(metadataTree, checkpointPath)
219→				if sessionPrompt != "" {
220→					sessionPrompts = []string{sessionPrompt}
221→				}
222→			}
223→		}
224→
225→		points = append(points, RewindPoint{
226→			ID:             c.Hash.String(),
227→			Message:        message,
228→			Date:           c.Author.When,
229→			IsLogsOnly:     true,
230→			CheckpointID:   cpInfo.CheckpointID,
231→			Agent:          cpInfo.Agent,
232→			SessionID:      cpInfo.SessionID,
233→			SessionPrompt:  sessionPrompt,
234→			SessionCount:   cpInfo.SessionCount,
235→			SessionIDs:     cpInfo.SessionIDs,
236→			SessionPrompts: sessionPrompts,
237→		})
238→
239→		return nil
240→	})
241→
242→	if err != nil && !errors.Is(err, errStop) {
243→		return nil, fmt.Errorf("error iterating commits: %w", err)
244→	}
245→
246→	if len(points) > limit {
247→		points = points[:limit]
248→	}
249→
250→	return points, nil
251→}

