127→// GetLogsOnlyRewindPoints finds commits in the current branch's history that have
128→// condensed session logs on the entire/checkpoints/v1 branch. These are commits that
129→// were created with session data but the shadow branch has been condensed.
130→//
131→// The function works by:
132→// 1. Getting all checkpoints from the entire/checkpoints/v1 branch
133→// 2. Building a map of checkpoint ID -> checkpoint info
134→// 3. Scanning the current branch history for commits with Entire-Checkpoint trailers
135→// 4. Matching by checkpoint ID (stable across amend/rebase)
136→func (s *ManualCommitStrategy) GetLogsOnlyRewindPoints(ctx context.Context, limit int) ([]RewindPoint, error) {
137→	repo, err := OpenRepository(ctx)
138→	if err != nil {
139→		return nil, err
140→	}
141→
142→	// Get all checkpoints from entire/checkpoints/v1 branch
143→	checkpoints, err := s.listCheckpoints(ctx)
144→	if err != nil {
145→		// No checkpoints yet is fine
146→		return nil, nil //nolint:nilerr // Expected when no checkpoints exist
147→	}
148→
149→	if len(checkpoints) == 0 {
150→		return nil, nil
151→	}
152→
153→	// Build map of checkpoint ID -> checkpoint info
154→	// Checkpoint ID is the stable link from Entire-Checkpoint trailer
155→	checkpointInfoMap := make(map[id.CheckpointID]CheckpointInfo)
156→	for _, cp := range checkpoints {
157→		if !cp.CheckpointID.IsEmpty() {
158→			checkpointInfoMap[cp.CheckpointID] = cp
159→		}
160→	}
161→
162→	// Get metadata branch tree for reading session prompts (best-effort, ignore errors)
163→	metadataTree, _ := GetMetadataBranchTree(repo) //nolint:errcheck // Best-effort for session prompts
164→
165→	head, err := repo.Head()
166→	if err != nil {
167→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
168→	}
169→
170→	// Use LogOptions with Order=LogOrderCommitterTime to traverse all parents of merge commits.
171→	iter, err := repo.Log(&git.LogOptions{
172→		From:  head.Hash(),
173→		Order: git.LogOrderCommitterTime,
174→	})
175→	if err != nil {
176→		return nil, fmt.Errorf("failed to get commit log: %w", err)
177→	}
178→
179→	var points []RewindPoint
180→	count := 0
181→
182→	err = iter.ForEach(func(c *object.Commit) error {
183→		if err := ctx.Err(); err != nil {
184→			return err //nolint:wrapcheck // Propagating context cancellation
185→		}
186→		if count >= logsOnlyScanLimit {
187→			return errStop
188→		}
189→		count++
190→
191→		// Extract all checkpoint IDs from Entire-Checkpoint trailers.
192→		// Squash merge commits may contain multiple trailers from the original commits.
193→		allCpIDs := trailers.ParseAllCheckpoints(c.Message)
194→		if len(allCpIDs) == 0 {
195→			return nil
196→		}
197→
198→		// Resolve to the latest checkpoint by creation time (consistent with `entire resume`).
199→		cpInfo, found := resolveLatestCheckpointFromMap(allCpIDs, checkpointInfoMap, metadataTree)
200→		if !found {
201→			return nil
202→		}
203→
204→		// Create logs-only rewind point
205→		message := strings.Split(c.Message, "\n")[0]
206→
207→		// Read session prompts from metadata tree
208→		var sessionPrompt string
209→		var sessionPrompts []string
210→		if metadataTree != nil {
211→			checkpointPath := paths.CheckpointPath(cpInfo.CheckpointID) //nolint:staticcheck // already present in codebase
212→			// For multi-session checkpoints, read all prompts
213→			if cpInfo.SessionCount > 1 && len(cpInfo.SessionIDs) > 1 {
214→				sessionPrompts = ReadAllSessionPromptsFromTree(metadataTree, checkpointPath, cpInfo.SessionCount, cpInfo.SessionIDs)
215→				// Use the last (most recent) prompt as the main session prompt
216→				if len(sessionPrompts) > 0 {
217→					sessionPrompt = sessionPrompts[len(sessionPrompts)-1]
218→				}
219→			} else {
220→				sessionPrompt = ReadSessionPromptFromTree(metadataTree, checkpointPath)
221→				if sessionPrompt != "" {
222→					sessionPrompts = []string{sessionPrompt}
223→				}
224→			}
225→		}
226→
227→		points = append(points, RewindPoint{
228→			ID:             c.Hash.String(),
229→			Message:        message,
230→			Date:           c.Author.When,
231→			IsLogsOnly:     true,
232→			CheckpointID:   cpInfo.CheckpointID,
233→			Agent:          cpInfo.Agent,
234→			SessionID:      cpInfo.SessionID,
235→			SessionPrompt:  sessionPrompt,
236→			SessionCount:   cpInfo.SessionCount,
237→			SessionIDs:     cpInfo.SessionIDs,
238→			SessionPrompts: sessionPrompts,
239→		})
240→
241→		return nil
242→	})
243→
244→	if err != nil && !errors.Is(err, errStop) {
245→		return nil, fmt.Errorf("error iterating commits: %w", err)
246→	}
247→
248→	if len(points) > limit {
249→		points = points[:limit]
250→	}
251→
252→	return points, nil
253→}
254→
255→// resolveLatestCheckpointFromMap picks the checkpoint with the latest CreatedAt
256→// from a list of checkpoint IDs. Filters to IDs present in infoMap, then uses
257→// CollectCheckpointsByAge for timestamp-based resolution from the metadata tree.
258→// For a single checkpoint, returns it directly without tree reads.
259→func resolveLatestCheckpointFromMap(cpIDs []id.CheckpointID, infoMap map[id.CheckpointID]CheckpointInfo, metadataTree *object.Tree) (CheckpointInfo, bool) {
260→	// Filter to IDs that have metadata
261→	var validIDs []id.CheckpointID
262→	for _, cpID := range cpIDs {
263→		if _, ok := infoMap[cpID]; ok {
264→			validIDs = append(validIDs, cpID)
265→		}
266→	}
267→	if len(validIDs) == 0 {
268→		return CheckpointInfo{}, false
269→	}
270→	if len(validIDs) == 1 {
271→		return infoMap[validIDs[0]], true
272→	}
273→
274→	// Multiple checkpoints: resolve by CreatedAt using metadata tree
275→	if metadataTree != nil {
276→		sorted := CollectCheckpointsByAge(metadataTree, validIDs)
277→		if len(sorted) > 0 {
278→			latest := sorted[len(sorted)-1]
279→			if info, ok := infoMap[latest.CheckpointID]; ok {
280→				return info, true
281→			}
282→		}
283→	}
284→
285→	// Fallback: use the info map's CreatedAt for ordering
286→	info := infoMap[validIDs[0]]
287→	for _, cpID := range validIDs[1:] {
288→		if candidate := infoMap[cpID]; candidate.CreatedAt.After(info.CreatedAt) {
289→			info = candidate
290→		}
291→	}
292→	return info, true
293→}
