295→// Rewind restores the working directory to a checkpoint.
296→//
297→
298→func (s *ManualCommitStrategy) Rewind(ctx context.Context, point RewindPoint) error {
299→	repo, err := OpenRepository(ctx)
300→	if err != nil {
301→		return fmt.Errorf("failed to open git repository: %w", err)
302→	}
303→
304→	// Get the checkpoint commit
305→	commitHash := plumbing.NewHash(point.ID)
306→	commit, err := repo.CommitObject(commitHash)
307→	if err != nil {
308→		return fmt.Errorf("failed to get commit: %w", err)
309→	}
310→
311→	tree, err := commit.Tree()
312→	if err != nil {
313→		return fmt.Errorf("failed to get tree: %w", err)
314→	}
315→
316→	// Reset the shadow branch to the rewound checkpoint
317→	// This ensures the next checkpoint will only include prompts from this point forward
318→	if err := s.resetShadowBranchToCheckpoint(ctx, repo, commit); err != nil {
319→		// Log warning but don't fail - file restoration is the primary operation
320→		fmt.Fprintf(os.Stderr, "[entire] Warning: failed to reset shadow branch: %v\n", err)
321→	}
322→
323→	// Load session state to get untracked files that existed at session start
324→	sessionID, hasSessionTrailer := trailers.ParseSession(commit.Message)
325→	var preservedUntrackedFiles map[string]bool
326→	if hasSessionTrailer {
327→		state, stateErr := s.loadSessionState(ctx, sessionID)
328→		if stateErr == nil && state != nil && len(state.UntrackedFilesAtStart) > 0 {
329→			preservedUntrackedFiles = make(map[string]bool)
330→			for _, f := range state.UntrackedFilesAtStart {
331→				preservedUntrackedFiles[f] = true
332→			}
333→		}
334→	}
335→
336→	// Build set of files in the checkpoint tree (excluding metadata)
337→	checkpointFiles := make(map[string]bool)
338→	err = tree.Files().ForEach(func(f *object.File) error {
339→		if err := ctx.Err(); err != nil {
340→			return err //nolint:wrapcheck // Propagating context cancellation
341→		}
342→		if !strings.HasPrefix(f.Name, entireDir) {
343→			checkpointFiles[f.Name] = true
344→		}
345→		return nil
346→	})
347→	if err != nil {
348→		return fmt.Errorf("failed to list checkpoint files: %w", err)
349→	}
350→
351→	// Get HEAD tree to identify tracked files
352→	head, err := repo.Head()
353→	if err != nil {
354→		return fmt.Errorf("failed to get HEAD: %w", err)
355→	}
356→	headCommit, err := repo.CommitObject(head.Hash())
357→	if err != nil {
358→		return fmt.Errorf("failed to get HEAD commit: %w", err)
359→	}
360→	headTree, err := headCommit.Tree()
361→	if err != nil {
362→		return fmt.Errorf("failed to get HEAD tree: %w", err)
363→	}
364→
365→	// Build set of files tracked in HEAD
366→	trackedFiles := make(map[string]bool)
367→	//nolint:errcheck // Error is not critical for rewind
368→	_ = headTree.Files().ForEach(func(f *object.File) error {
369→		if err := ctx.Err(); err != nil {
370→			return err //nolint:wrapcheck // Propagating context cancellation
371→		}
372→		trackedFiles[f.Name] = true
373→		return nil
374→	})
375→
376→	// Get repository root to walk from there
377→	repoRoot, err := paths.WorktreeRoot(ctx)
378→	if err != nil {
379→		repoRoot = "." // Fallback to current directory
380→	}
381→
382→	// Find and delete untracked files that aren't in the checkpoint.
383→	// Uses git ls-files to only consider non-ignored files, avoiding walks through
384→	// large ignored directories like node_modules/.
385→	untrackedNow, err := collectUntrackedFiles(ctx)
386→	if err != nil {
387→		// Non-fatal - continue with restoration
388→		fmt.Fprintf(os.Stderr, "Warning: error listing untracked files: %v\n", err)
389→	}
390→	for _, relPath := range untrackedNow {
391→		// If file is in checkpoint, it will be restored
392→		if checkpointFiles[relPath] {
393→			continue
394→		}
395→
396→		// If file is tracked in HEAD, don't delete (user's committed work)
397→		if trackedFiles[relPath] {
398→			continue
399→		}
400→
401→		// If file existed at session start, preserve it (untracked user files)
402→		if preservedUntrackedFiles[relPath] {
403→			continue
404→		}
405→
406→		// File is untracked and not in checkpoint - delete it
407→		absPath := filepath.Join(repoRoot, relPath)
408→		if removeErr := os.Remove(absPath); removeErr == nil {
409→			fmt.Fprintf(os.Stderr, "  Deleted: %s\n", relPath)
410→		}
411→	}
412→
413→	// Restore files from checkpoint
414→	err = tree.Files().ForEach(func(f *object.File) error {
415→		if err := ctx.Err(); err != nil {
416→			return err //nolint:wrapcheck // Propagating context cancellation
417→		}
418→		// Skip metadata directories - these are for checkpoint storage, not working dir
419→		if strings.HasPrefix(f.Name, entireDir) {
420→			return nil
421→		}
422→
423→		contents, err := f.Contents()
424→		if err != nil {
425→			return fmt.Errorf("failed to read file %s: %w", f.Name, err)
426→		}
427→
428→		// Ensure directory exists
429→		dir := filepath.Dir(f.Name)
430→		if dir != "." {
431→			//nolint:gosec // G301: Need 0o755 for user directories during rewind
432→			if err := os.MkdirAll(dir, 0o755); err != nil {
433→				return fmt.Errorf("failed to create directory %s: %w", dir, err)
434→			}
435→		}
436→
437→		// Write file with appropriate permissions
438→		var perm os.FileMode = 0o644
439→		if f.Mode == filemode.Executable {
440→			perm = 0o755
441→		}
442→		if err := os.WriteFile(f.Name, []byte(contents), perm); err != nil {
443→			return fmt.Errorf("failed to write file %s: %w", f.Name, err)
444→		}
445→
446→		fmt.Fprintf(os.Stderr, "  Restored: %s\n", f.Name)
447→		return nil
448→	})
449→	if err != nil {
450→		return fmt.Errorf("failed to iterate tree files: %w", err)
451→	}
452→
453→	fmt.Println()
454→	if len(point.ID) >= 7 {
455→		fmt.Printf("Restored files from shadow commit %s\n", point.ID[:7])
456→	} else {
457→		fmt.Printf("Restored files from shadow commit %s\n", point.ID)
458→	}
459→	fmt.Println()
460→
461→	return nil
462→}
