464→// resetShadowBranchToCheckpoint resets the shadow branch HEAD to the given checkpoint.
465→// This ensures that when the user commits after rewinding, the next checkpoint will only
466→// include prompts from the rewound point, not prompts from later checkpoints.
467→func (s *ManualCommitStrategy) resetShadowBranchToCheckpoint(ctx context.Context, repo *git.Repository, commit *object.Commit) error {
468→	// Extract session ID from the checkpoint commit's Entire-Session trailer
469→	sessionID, found := trailers.ParseSession(commit.Message)
470→	if !found {
471→		return errors.New("checkpoint has no Entire-Session trailer")
472→	}
473→
474→	// Load session state to get the shadow branch name
475→	state, err := s.loadSessionState(ctx, sessionID)
476→	if err != nil {
477→		return fmt.Errorf("failed to load session state: %w", err)
478→	}
479→	if state == nil {
480→		return fmt.Errorf("session %s not found", sessionID)
481→	}
482→
483→	// Reset the shadow branch to the checkpoint commit
484→	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
485→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
486→
487→	// Update the reference to point to the checkpoint commit
488→	ref := plumbing.NewHashReference(refName, commit.Hash)
489→	if err := repo.Storer.SetReference(ref); err != nil {
490→		return fmt.Errorf("failed to update shadow branch: %w", err)
491→	}
492→
493→	fmt.Fprintf(os.Stderr, "[entire] Reset shadow branch %s to checkpoint %s\n", shadowBranchName, commit.Hash.String()[:7])
494→	return nil
495→}
