505→// PreviewRewind returns what will happen if rewinding to the given point.
506→// This allows showing warnings about untracked files that will be deleted.
507→func (s *ManualCommitStrategy) PreviewRewind(ctx context.Context, point RewindPoint) (*RewindPreview, error) {
508→	// Logs-only points don't modify the working directory
509→	if point.IsLogsOnly {
510→		return &RewindPreview{}, nil
511→	}
512→
513→	repo, err := OpenRepository(ctx)
514→	if err != nil {
515→		return nil, fmt.Errorf("failed to open git repository: %w", err)
516→	}
517→
518→	// Get the checkpoint commit
519→	commitHash := plumbing.NewHash(point.ID)
520→	commit, err := repo.CommitObject(commitHash)
521→	if err != nil {
522→		return nil, fmt.Errorf("failed to get commit: %w", err)
523→	}
524→
525→	tree, err := commit.Tree()
526→	if err != nil {
527→		return nil, fmt.Errorf("failed to get tree: %w", err)
528→	}
529→
530→	// Load session state to get untracked files that existed at session start
531→	sessionID, hasSessionTrailer := trailers.ParseSession(commit.Message)
532→	var preservedUntrackedFiles map[string]bool
533→	if hasSessionTrailer {
534→		state, stateErr := s.loadSessionState(ctx, sessionID)
535→		if stateErr == nil && state != nil && len(state.UntrackedFilesAtStart) > 0 {
536→			preservedUntrackedFiles = make(map[string]bool)
537→			for _, f := range state.UntrackedFilesAtStart {
538→				preservedUntrackedFiles[f] = true
539→			}
540→		}
541→	}
542→
543→	// Build set of files in the checkpoint tree (excluding metadata)
544→	checkpointFiles := make(map[string]bool)
545→	var filesToRestore []string
546→	err = tree.Files().ForEach(func(f *object.File) error {
547→		if err := ctx.Err(); err != nil {
548→			return err //nolint:wrapcheck // Propagating context cancellation
549→		}
550→		if !strings.HasPrefix(f.Name, entireDir) {
551→			checkpointFiles[f.Name] = true
552→			filesToRestore = append(filesToRestore, f.Name)
553→		}
554→		return nil
555→	})
556→	if err != nil {
557→		return nil, fmt.Errorf("failed to list checkpoint files: %w", err)
558→	}
559→
560→	// Get HEAD tree to identify tracked files
561→	head, err := repo.Head()
562→	if err != nil {
563→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
564→	}
565→	headCommit, err := repo.CommitObject(head.Hash())
566→	if err != nil {
567→		return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
568→	}
569→	headTree, err := headCommit.Tree()
570→	if err != nil {
571→		return nil, fmt.Errorf("failed to get HEAD tree: %w", err)
572→	}
573→
574→	// Build set of files tracked in HEAD
575→	trackedFiles := make(map[string]bool)
576→	//nolint:errcheck // Error is not critical for preview
577→	_ = headTree.Files().ForEach(func(f *object.File) error {
578→		if err := ctx.Err(); err != nil {
579→			return err //nolint:wrapcheck // Propagating context cancellation
580→		}
581→		trackedFiles[f.Name] = true
582→		return nil
583→	})
584→
585→	// Find untracked files that would be deleted.
586→	// Uses git ls-files to only consider non-ignored files.
587→	var filesToDelete []string
588→	untrackedNow, untrackedErr := collectUntrackedFiles(ctx)
589→	if untrackedErr != nil {
590→		fmt.Fprintf(os.Stderr, "Warning: could not list untracked files for preview: %v\n", untrackedErr)
591→		return &RewindPreview{
592→			FilesToRestore: filesToRestore,
593→			FilesToDelete:  filesToDelete,
594→		}, nil
595→	}
596→	for _, relPath := range untrackedNow {
597→		if checkpointFiles[relPath] {
598→			continue
599→		}
600→		if trackedFiles[relPath] {
601→			continue
602→		}
603→		if preservedUntrackedFiles[relPath] {
604→			continue
605→		}
606→		filesToDelete = append(filesToDelete, relPath)
607→	}
608→
609→	// Sort for consistent output
610→	sort.Strings(filesToRestore)
611→	sort.Strings(filesToDelete)
612→
613→	return &RewindPreview{
614→		FilesToRestore: filesToRestore,
615→		FilesToDelete:  filesToDelete,
616→	}, nil
617→}
