619→// RestoreLogsOnly restores session logs from a logs-only rewind point.
620→// This fetches the transcript from entire/checkpoints/v1 and writes it to the agent's session directory.
621→// Does not modify the working directory.
622→// When multiple sessions were condensed to the same checkpoint, ALL sessions are restored.
623→// If force is false, prompts for confirmation when local logs have newer timestamps.
624→// Returns info about each restored session so callers can print correct per-session resume commands.
625→func (s *ManualCommitStrategy) RestoreLogsOnly(ctx context.Context, point RewindPoint, force bool) ([]RestoredSession, error) {
626→	if !point.IsLogsOnly {
627→		return nil, errors.New("not a logs-only rewind point")
628→	}
