830→func (s *ManualCommitStrategy) classifySessionsForRestore(ctx context.Context, repoRoot string, store cpkg.Store, checkpointID id.CheckpointID, summary *cpkg.CheckpointSummary) []SessionRestoreInfo {
831→	var sessions []SessionRestoreInfo
832→
833→	totalSessions := len(summary.Sessions)
834→	// Check all sessions (0-based indexing)
835→	for i := range totalSessions {
836→		content, err := store.ReadSessionContent(ctx, checkpointID, i)
837→		if err != nil || content == nil || len(content.Transcript) == 0 {
838→			continue
839→		}
840→
841→		sessionID := content.Metadata.SessionID
842→		if sessionID == "" || content.Metadata.Agent == "" {
843→			continue
844→		}
845→
846→		sessionAgent, agErr := ResolveAgentForRewind(content.Metadata.Agent)
847→		if agErr != nil {
848→			continue
849→		}
850→
851→		// Compute transcript path from current repo location for cross-machine portability.
852→		sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
853→		if dirErr != nil {
854→			continue
855→		}
856→		localPath := sessionAgent.ResolveSessionFile(sessionAgentDir, sessionID)
857→
858→		localTime := paths.GetLastTimestampFromFile(localPath)
859→		checkpointTime := paths.GetLastTimestampFromBytes(content.Transcript)
860→		status := ClassifyTimestamps(localTime, checkpointTime)
861→
862→		sessions = append(sessions, SessionRestoreInfo{
863→			SessionID:      sessionID,
864→			Prompt:         ExtractFirstPrompt(content.Prompts),
865→			Status:         status,
866→			LocalTime:      localTime,
867→			CheckpointTime: checkpointTime,
868→		})
869→	}
870→
871→	return sessions
872→}
