874→// ClassifyTimestamps determines the restore status based on local and checkpoint timestamps.
875→func ClassifyTimestamps(localTime, checkpointTime time.Time) SessionRestoreStatus {
876→	// Local file doesn't exist (no timestamp found)
877→	if localTime.IsZero() {
878→		return StatusNew
879→	}
880→
881→	// Can't determine checkpoint time - treat as new/safe
882→	if checkpointTime.IsZero() {
883→		return StatusNew
884→	}
885→
886→	// Compare timestamps
887→	if localTime.After(checkpointTime) {
888→		return StatusLocalNewer
889→	}
890→	if checkpointTime.After(localTime) {
891→		return StatusCheckpointNewer
892→	}
893→	return StatusUnchanged
894→}
