427→// CollectCheckpointsByAge reads metadata for each checkpoint ID from the tree,
428→// skips any that can't be read, and returns them sorted by CreatedAt ascending.
429→// The newest checkpoint is last. This is used by both resume and rewind to resolve
430→// squash merge commits that contain multiple Entire-Checkpoint trailers.
431→func CollectCheckpointsByAge(tree *object.Tree, checkpointIDs []id.CheckpointID) []*CheckpointInfo {
432→	var checkpoints []*CheckpointInfo
433→	for _, cpID := range checkpointIDs {
434→		metadata, err := ReadCheckpointMetadata(tree, cpID.Path())
435→		if err != nil {
436→			continue
437→		}
438→		checkpoints = append(checkpoints, metadata)
439→	}
440→	sort.Slice(checkpoints, func(i, j int) bool {
441→		return checkpoints[i].CreatedAt.Before(checkpoints[j].CreatedAt)
442→	})
443→	return checkpoints
444→}
