475→// CheckpointIDs lists all checkpoint IDs from the tree at the tip of the
476→// checkpoint branch. It parses the two-level directory structure
477→// ({prefix}/{suffix}/metadata.json) and returns the concatenated IDs.
478→func CheckpointIDs(t *testing.T, dir string) []string {
479→	t.Helper()
480→	out := gitOutputSafe(dir, "ls-tree", "-r", "--name-only", "entire/checkpoints/v1")
481→	if out == "" {
482→		return nil
483→	}
484→	seen := map[string]bool{}
485→	var ids []string
486→	for _, line := range strings.Split(strings.TrimSpace(out), "\n") {
487→		// Match {prefix}/{suffix}/metadata.json (top-level, not session-level)
488→		parts := strings.Split(line, "/")
489→		if len(parts) == 3 && parts[2] == "metadata.json" {
490→			id := parts[0] + parts[1]
491→			if !seen[id] {
492→				seen[id] = true
493→				ids = append(ids, id)
494→			}
495→		}
496→	}
497→	return ids
498→}
