536→// WaitForSessionMetadata polls until session metadata exists on the checkpoint
537→// branch for the given checkpoint ID and session index, then returns it.
538→// This handles the race where the checkpoint branch advances before session
539→// metadata is fully committed.
540→func WaitForSessionMetadata(t *testing.T, dir string, checkpointID string, sessionIndex int, timeout time.Duration) SessionMetadata {
541→	t.Helper()
542→
543→	path := fmt.Sprintf("%s/%d/metadata.json", CheckpointPath(checkpointID), sessionIndex)
544→	blob := "entire/checkpoints/v1:" + path
545→
546→	deadline := time.Now().Add(timeout)
547→	for time.Now().Before(deadline) {
548→		raw := gitOutputSafe(dir, "show", blob)
549→		if raw != "" {
550→			var meta SessionMetadata
551→			if err := json.Unmarshal([]byte(raw), &meta); err != nil {
552→				t.Fatalf("unmarshal session metadata from %s: %v", blob, err)
553→			}
554→			return meta
555→		}
556→		time.Sleep(500 * time.Millisecond)
557→	}
558→	t.Fatalf("session metadata %s did not appear within %s", blob, timeout)
559→	return SessionMetadata{}
560→}
