 27→// GetRewindPoints returns available rewind points.
 28→// Uses checkpoint.GitStore.ListTemporaryCheckpoints for reading from shadow branches.
 29→func (s *ManualCommitStrategy) GetRewindPoints(ctx context.Context, limit int) ([]RewindPoint, error) {
 30→	repo, err := OpenRepository(ctx)
 31→	if err != nil {
 32→		return nil, fmt.Errorf("failed to open git repository: %w", err)
 33→	}
 34→
 35→	// Get checkpoint store
 36→	store, err := s.getCheckpointStore()
 37→	if err != nil {
 38→		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
 39→	}
 40→
 41→	// Get current HEAD to find matching shadow branch
 42→	head, err := repo.Head()
 43→	if err != nil {
 44→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
 45→	}
 46→
 47→	// Find sessions for current HEAD
 48→	sessions, err := s.findSessionsForCommit(ctx, head.Hash().String())
 49→	if err != nil {
 50→		// Log error but continue to check for logs-only points
 51→		sessions = nil
 52→	}
 53→
 54→	var allPoints []RewindPoint
 55→
 56→	// Collect checkpoint points from active sessions using checkpoint.GitStore
 57→	// Cache session prompts by session ID to avoid re-reading the same prompt file
 58→	sessionPrompts := make(map[string]string)
 59→
 60→	for _, state := range sessions {
 61→		checkpoints, err := store.ListTemporaryCheckpoints(ctx, state.BaseCommit, state.WorktreeID, state.SessionID, limit)
 62→		if err != nil {
 63→			continue // Error reading checkpoints, skip this session
 64→		}
 65→
 66→		for _, cp := range checkpoints {
 67→			// Get session prompt (cached by session ID)
 68→			sessionPrompt, ok := sessionPrompts[cp.SessionID]
 69→			if !ok {
 70→				sessionPrompt = readSessionPrompt(repo, cp.CommitHash, cp.MetadataDir)
 71→				sessionPrompts[cp.SessionID] = sessionPrompt
 72→			}
 73→
 74→			allPoints = append(allPoints, RewindPoint{
 75→				ID:               cp.CommitHash.String(),
 76→				Message:          cp.Message,
 77→				MetadataDir:      cp.MetadataDir,
 78→				Date:             cp.Timestamp,
 79→				IsTaskCheckpoint: cp.IsTaskCheckpoint,
 80→				ToolUseID:        cp.ToolUseID,
 81→				SessionID:        cp.SessionID,
 82→				SessionPrompt:    sessionPrompt,
 83→				Agent:            state.AgentType,
 84→			})
 85→		}
 86→	}
 87→
 88→	// Sort by date, most recent first
 89→	sort.Slice(allPoints, func(i, j int) bool {
 90→		return allPoints[i].Date.After(allPoints[j].Date)
 91→	})
 92→
 93→	if len(allPoints) > limit {
 94→		allPoints = allPoints[:limit]
 95→	}
 96→
 97→	// Also include logs-only points from commit history
 98→	logsOnlyPoints, err := s.GetLogsOnlyRewindPoints(ctx, limit)
 99→	if err == nil && len(logsOnlyPoints) > 0 {
100→		// Build set of existing point IDs for deduplication
101→		existingIDs := make(map[string]bool)
102→		for _, p := range allPoints {
103→			existingIDs[p.ID] = true
104→		}
105→
106→		// Add logs-only points that aren't already in the list
107→		for _, p := range logsOnlyPoints {
108→			if !existingIDs[p.ID] {
109→				allPoints = append(allPoints, p)
110→			}
111→		}
112→
113→		// Re-sort by date
114→		sort.Slice(allPoints, func(i, j int) bool {
115→			return allPoints[i].Date.After(allPoints[j].Date)
116→		})
117→
118→		// Re-trim to limit
119→		if len(allPoints) > limit {
120→			allPoints = allPoints[:limit]
121→		}
122→	}
123→
124→	return allPoints, nil
125→}
126→
127→// GetLogsOnlyRewindPoints finds commits in the current branch's history that have
128→// condensed session logs on the entire/checkpoints/v1 branch. These are commits that
129→// were created with session data but the shadow branch has been condensed.
130→//
131→// The function works by:
132→// 1. Getting all checkpoints from the entire/checkpoints/v1 branch
133→// 2. Building a map of checkpoint ID -> checkpoint info
134→// 3. Scanning the current branch history for commits with Entire-Checkpoint trailers
135→// 4. Matching by checkpoint ID (stable across amend/rebase)
136→func (s *ManualCommitStrategy) GetLogsOnlyRewindPoints(ctx context.Context, limit int) ([]RewindPoint, error) {
137→	repo, err := OpenRepository(ctx)
138→	if err != nil {
139→		return nil, err
140→	}
141→
142→	// Get all checkpoints from entire/checkpoints/v1 branch
143→	checkpoints, err := s.listCheckpoints(ctx)
144→	if err != nil {
145→		// No checkpoints yet is fine
146→		return nil, nil //nolint:nilerr // Expected when no checkpoints exist
147→	}
148→
149→	if len(checkpoints) == 0 {
150→		return nil, nil
151→	}
152→
153→	// Build map of checkpoint ID -> checkpoint info
154→	// Checkpoint ID is the stable link from Entire-Checkpoint trailer
155→	checkpointInfoMap := make(map[id.CheckpointID]CheckpointInfo)
156→	for _, cp := range checkpoints {
157→		if !cp.CheckpointID.IsEmpty() {
158→			checkpointInfoMap[cp.CheckpointID] = cp
159→		}
160→	}
161→
162→	// Get metadata branch tree for reading session prompts (best-effort, ignore errors)
163→	metadataTree, _ := GetMetadataBranchTree(repo) //nolint:errcheck // Best-effort for session prompts
164→
165→	head, err := repo.Head()
166→	if err != nil {
167→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
168→	}
169→
170→	// Use LogOptions with Order=LogOrderCommitterTime to traverse all parents of merge commits.
171→	iter, err := repo.Log(&git.LogOptions{
172→		From:  head.Hash(),
173→		Order: git.LogOrderCommitterTime,
174→	})
175→	if err != nil {
176→		return nil, fmt.Errorf("failed to get commit log: %w", err)
177→	}
178→
179→	var points []RewindPoint
180→	count := 0
181→
182→	err = iter.ForEach(func(c *object.Commit) error {
183→		if err := ctx.Err(); err != nil {
184→			return err //nolint:wrapcheck // Propagating context cancellation
185→		}
186→		if count >= logsOnlyScanLimit {
187→			return errStop
188→		}
189→		count++
190→
191→		// Extract all checkpoint IDs from Entire-Checkpoint trailers.
192→		// Squash merge commits may contain multiple trailers from the original commits.
193→		allCpIDs := trailers.ParseAllCheckpoints(c.Message)
194→		if len(allCpIDs) == 0 {
195→			return nil
196→		}
197→
198→		// Resolve to the latest checkpoint by creation time (consistent with `entire resume`).
199→		cpInfo, found := resolveLatestCheckpointFromMap(allCpIDs, checkpointInfoMap)
200→		if !found {
201→			return nil
202→		}
203→
204→		// Create logs-only rewind point
205→		message := strings.Split(c.Message, "\n")[0]
206→
207→		// Read session prompts from metadata tree
208→		var sessionPrompt string
209→		var sessionPrompts []string
210→		if metadataTree != nil {
211→			checkpointPath := paths.CheckpointPath(cpInfo.CheckpointID) //nolint:staticcheck // already present in codebase
212→			// For multi-session checkpoints, read all prompts
213→			if cpInfo.SessionCount > 1 && len(cpInfo.SessionIDs) > 1 {
214→				sessionPrompts = ReadAllSessionPromptsFromTree(metadataTree, checkpointPath, cpInfo.SessionCount, cpInfo.SessionIDs)
215→				// Use the last (most recent) prompt as the main session prompt
216→				if len(sessionPrompts) > 0 {
217→					sessionPrompt = sessionPrompts[len(sessionPrompts)-1]
218→				}
219→			} else {
220→				sessionPrompt = ReadSessionPromptFromTree(metadataTree, checkpointPath)
221→				if sessionPrompt != "" {
222→					sessionPrompts = []string{sessionPrompt}
223→				}
224→			}
225→		}
226→
227→		points = append(points, RewindPoint{
228→			ID:             c.Hash.String(),
229→			Message:        message,
230→			Date:           c.Author.When,
231→			IsLogsOnly:     true,
232→			CheckpointID:   cpInfo.CheckpointID,
233→			Agent:          cpInfo.Agent,
234→			SessionID:      cpInfo.SessionID,
235→			SessionPrompt:  sessionPrompt,
236→			SessionCount:   cpInfo.SessionCount,
237→			SessionIDs:     cpInfo.SessionIDs,
238→			SessionPrompts: sessionPrompts,
239→		})
240→
241→		return nil
242→	})
243→
244→	if err != nil && !errors.Is(err, errStop) {
245→		return nil, fmt.Errorf("error iterating commits: %w", err)
246→	}
247→
248→	if len(points) > limit {
249→		points = points[:limit]
250→	}
251→
252→	return points, nil
253→}
254→
255→// resolveLatestCheckpointFromMap picks the checkpoint with the latest CreatedAt
256→// from a list of checkpoint IDs. Filters to IDs present in infoMap, then picks
257→// the one with the most recent CreatedAt. The infoMap is populated by
258→// listCheckpoints which already reads CreatedAt from the metadata tree, so no
259→// additional tree I/O is needed here.
260→func resolveLatestCheckpointFromMap(cpIDs []id.CheckpointID, infoMap map[id.CheckpointID]CheckpointInfo) (CheckpointInfo, bool) {
261→	var found bool
262→	var latest CheckpointInfo
263→	for _, cpID := range cpIDs {
264→		info, ok := infoMap[cpID]
265→		if !ok {
266→			continue
267→		}
268→		if !found || info.CreatedAt.After(latest.CreatedAt) {
269→			latest = info
270→			found = true
271→		}
272→	}
273→	return latest, found
274→}
