276→// Rewind restores the working directory to a checkpoint.
277→//
278→
279→func (s *ManualCommitStrategy) Rewind(ctx context.Context, point RewindPoint) error {
280→	repo, err := OpenRepository(ctx)
281→	if err != nil {
282→		return fmt.Errorf("failed to open git repository: %w", err)
283→	}
284→
285→	// Get the checkpoint commit
286→	commitHash := plumbing.NewHash(point.ID)
287→	commit, err := repo.CommitObject(commitHash)
288→	if err != nil {
289→		return fmt.Errorf("failed to get commit: %w", err)
290→	}
291→
292→	tree, err := commit.Tree()
293→	if err != nil {
294→		return fmt.Errorf("failed to get tree: %w", err)
295→	}
296→
297→	// Reset the shadow branch to the rewound checkpoint
298→	// This ensures the next checkpoint will only include prompts from this point forward
299→	if err := s.resetShadowBranchToCheckpoint(ctx, repo, commit); err != nil {
300→		// Log warning but don't fail - file restoration is the primary operation
301→		fmt.Fprintf(os.Stderr, "[entire] Warning: failed to reset shadow branch: %v\n", err)
302→	}
303→
304→	// Load session state to get untracked files that existed at session start
305→	sessionID, hasSessionTrailer := trailers.ParseSession(commit.Message)
306→	var preservedUntrackedFiles map[string]bool
307→	if hasSessionTrailer {
308→		state, stateErr := s.loadSessionState(ctx, sessionID)
309→		if stateErr == nil && state != nil && len(state.UntrackedFilesAtStart) > 0 {
310→			preservedUntrackedFiles = make(map[string]bool)
311→			for _, f := range state.UntrackedFilesAtStart {
312→				preservedUntrackedFiles[f] = true
313→			}
314→		}
315→	}
316→
317→	// Build set of files in the checkpoint tree (excluding metadata)
318→	checkpointFiles := make(map[string]bool)
319→	err = tree.Files().ForEach(func(f *object.File) error {
320→		if err := ctx.Err(); err != nil {
321→			return err //nolint:wrapcheck // Propagating context cancellation
322→		}
323→		if !strings.HasPrefix(f.Name, entireDir) {
324→			checkpointFiles[f.Name] = true
325→		}
326→		return nil
327→	})
328→	if err != nil {
329→		return fmt.Errorf("failed to list checkpoint files: %w", err)
330→	}
331→
332→	// Get HEAD tree to identify tracked files
333→	head, err := repo.Head()
334→	if err != nil {
335→		return fmt.Errorf("failed to get HEAD: %w", err)
336→	}
337→	headCommit, err := repo.CommitObject(head.Hash())
338→	if err != nil {
339→		return fmt.Errorf("failed to get HEAD commit: %w", err)
340→	}
341→	headTree, err := headCommit.Tree()
342→	if err != nil {
343→		return fmt.Errorf("failed to get HEAD tree: %w", err)
344→	}
345→
346→	// Build set of files tracked in HEAD
347→	trackedFiles := make(map[string]bool)
348→	//nolint:errcheck // Error is not critical for rewind
349→	_ = headTree.Files().ForEach(func(f *object.File) error {
350→		if err := ctx.Err(); err != nil {
351→			return err //nolint:wrapcheck // Propagating context cancellation
352→		}
353→		trackedFiles[f.Name] = true
354→		return nil
355→	})
356→
357→	// Get repository root to walk from there
358→	repoRoot, err := paths.WorktreeRoot(ctx)
359→	if err != nil {
360→		repoRoot = "." // Fallback to current directory
361→	}
362→
363→	// Find and delete untracked files that aren't in the checkpoint.
364→	// Uses git ls-files to only consider non-ignored files, avoiding walks through
365→	// large ignored directories like node_modules/.
366→	untrackedNow, err := collectUntrackedFiles(ctx)
367→	if err != nil {
368→		// Non-fatal - continue with restoration
369→		fmt.Fprintf(os.Stderr, "Warning: error listing untracked files: %v\n", err)
370→	}
371→	for _, relPath := range untrackedNow {
372→		// If file is in checkpoint, it will be restored
373→		if checkpointFiles[relPath] {
374→			continue
375→		}
376→
377→		// If file is tracked in HEAD, don't delete (user's committed work)
378→		if trackedFiles[relPath] {
379→			continue
380→		}
381→
382→		// If file existed at session start, preserve it (untracked user files)
383→		if preservedUntrackedFiles[relPath] {
384→			continue
385→		}
386→
387→		// File is untracked and not in checkpoint - delete it
388→		absPath := filepath.Join(repoRoot, relPath)
389→		if removeErr := os.Remove(absPath); removeErr == nil {
390→			fmt.Fprintf(os.Stderr, "  Deleted: %s\n", relPath)
391→		}
392→	}
393→
394→	// Restore files from checkpoint
395→	err = tree.Files().ForEach(func(f *object.File) error {
396→		if err := ctx.Err(); err != nil {
397→			return err //nolint:wrapcheck // Propagating context cancellation
398→		}
399→		// Skip metadata directories - these are for checkpoint storage, not working dir
400→		if strings.HasPrefix(f.Name, entireDir) {
401→			return nil
402→		}
403→
404→		contents, err := f.Contents()
405→		if err != nil {
406→			return fmt.Errorf("failed to read file %s: %w", f.Name, err)
407→		}
408→
409→		// Ensure directory exists
410→		dir := filepath.Dir(f.Name)
411→		if dir != "." {
412→			//nolint:gosec // G301: Need 0o755 for user directories during rewind
413→			if err := os.MkdirAll(dir, 0o755); err != nil {
414→				return fmt.Errorf("failed to create directory %s: %w", dir, err)
415→			}
416→		}
417→
418→		// Write file with appropriate permissions
419→		var perm os.FileMode = 0o644
420→		if f.Mode == filemode.Executable {
421→			perm = 0o755
422→		}
423→		if err := os.WriteFile(f.Name, []byte(contents), perm); err != nil {
424→			return fmt.Errorf("failed to write file %s: %w", f.Name, err)
425→		}
426→
427→		fmt.Fprintf(os.Stderr, "  Restored: %s\n", f.Name)
428→		return nil
429→	})
430→	if err != nil {
431→		return fmt.Errorf("failed to iterate tree files: %w", err)
432→	}
433→
434→	fmt.Println()
435→	if len(point.ID) >= 7 {
436→		fmt.Printf("Restored files from shadow commit %s\n", point.ID[:7])
437→	} else {
438→		fmt.Printf("Restored files from shadow commit %s\n", point.ID)
439→	}
440→	fmt.Println()
441→
442→	return nil
443→}
