445→// resetShadowBranchToCheckpoint resets the shadow branch HEAD to the given checkpoint.
446→// This ensures that when the user commits after rewinding, the next checkpoint will only
447→// include prompts from the rewound point, not prompts from later checkpoints.
448→func (s *ManualCommitStrategy) resetShadowBranchToCheckpoint(ctx context.Context, repo *git.Repository, commit *object.Commit) error {
449→	// Extract session ID from the checkpoint commit's Entire-Session trailer
450→	sessionID, found := trailers.ParseSession(commit.Message)
451→	if !found {
452→		return errors.New("checkpoint has no Entire-Session trailer")
453→	}
454→
455→	// Load session state to get the shadow branch name
456→	state, err := s.loadSessionState(ctx, sessionID)
457→	if err != nil {
458→		return fmt.Errorf("failed to load session state: %w", err)
459→	}
460→	if state == nil {
461→		return fmt.Errorf("session %s not found", sessionID)
462→	}
463→
464→	// Reset the shadow branch to the checkpoint commit
465→	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
466→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
467→
468→	// Update the reference to point to the checkpoint commit
469→	ref := plumbing.NewHashReference(refName, commit.Hash)
470→	if err := repo.Storer.SetReference(ref); err != nil {
471→		return fmt.Errorf("failed to update shadow branch: %w", err)
472→	}
473→
474→	fmt.Fprintf(os.Stderr, "[entire] Reset shadow branch %s to checkpoint %s\n", shadowBranchName, commit.Hash.String()[:7])
475→	return nil
476→}
