478→// CanRewind checks if rewinding is possible.
479→// For manual-commit strategy, rewind restores files from a checkpoint - uncommitted changes are expected
480→// and will be replaced by the checkpoint contents. Returns true with a warning message showing
481→// what changes will be reverted.
482→func (s *ManualCommitStrategy) CanRewind(ctx context.Context) (bool, string, error) {
483→	return checkCanRewindWithWarning(ctx)
