486→// PreviewRewind returns what will happen if rewinding to the given point.
487→// This allows showing warnings about untracked files that will be deleted.
488→func (s *ManualCommitStrategy) PreviewRewind(ctx context.Context, point RewindPoint) (*RewindPreview, error) {
489→	// Logs-only points don't modify the working directory
490→	if point.IsLogsOnly {
491→		return &RewindPreview{}, nil
492→	}
493→
494→	repo, err := OpenRepository(ctx)
495→	if err != nil {
496→		return nil, fmt.Errorf("failed to open git repository: %w", err)
497→	}
498→
499→	// Get the checkpoint commit
500→	commitHash := plumbing.NewHash(point.ID)
501→	commit, err := repo.CommitObject(commitHash)
502→	if err != nil {
503→		return nil, fmt.Errorf("failed to get commit: %w", err)
504→	}
505→
506→	tree, err := commit.Tree()
507→	if err != nil {
508→		return nil, fmt.Errorf("failed to get tree: %w", err)
509→	}
510→
511→	// Load session state to get untracked files that existed at session start
512→	sessionID, hasSessionTrailer := trailers.ParseSession(commit.Message)
513→	var preservedUntrackedFiles map[string]bool
514→	if hasSessionTrailer {
515→		state, stateErr := s.loadSessionState(ctx, sessionID)
516→		if stateErr == nil && state != nil && len(state.UntrackedFilesAtStart) > 0 {
517→			preservedUntrackedFiles = make(map[string]bool)
518→			for _, f := range state.UntrackedFilesAtStart {
519→				preservedUntrackedFiles[f] = true
520→			}
521→		}
522→	}
523→
524→	// Build set of files in the checkpoint tree (excluding metadata)
525→	checkpointFiles := make(map[string]bool)
526→	var filesToRestore []string
527→	err = tree.Files().ForEach(func(f *object.File) error {
528→		if err := ctx.Err(); err != nil {
529→			return err //nolint:wrapcheck // Propagating context cancellation
530→		}
531→		if !strings.HasPrefix(f.Name, entireDir) {
532→			checkpointFiles[f.Name] = true
533→			filesToRestore = append(filesToRestore, f.Name)
534→		}
535→		return nil
536→	})
537→	if err != nil {
538→		return nil, fmt.Errorf("failed to list checkpoint files: %w", err)
539→	}
540→
541→	// Get HEAD tree to identify tracked files
542→	head, err := repo.Head()
543→	if err != nil {
544→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
545→	}
546→	headCommit, err := repo.CommitObject(head.Hash())
547→	if err != nil {
548→		return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
549→	}
550→	headTree, err := headCommit.Tree()
551→	if err != nil {
552→		return nil, fmt.Errorf("failed to get HEAD tree: %w", err)
553→	}
554→
555→	// Build set of files tracked in HEAD
556→	trackedFiles := make(map[string]bool)
557→	//nolint:errcheck // Error is not critical for preview
558→	_ = headTree.Files().ForEach(func(f *object.File) error {
559→		if err := ctx.Err(); err != nil {
560→			return err //nolint:wrapcheck // Propagating context cancellation
561→		}
562→		trackedFiles[f.Name] = true
563→		return nil
564→	})
565→
566→	// Find untracked files that would be deleted.
567→	// Uses git ls-files to only consider non-ignored files.
568→	var filesToDelete []string
569→	untrackedNow, untrackedErr := collectUntrackedFiles(ctx)
570→	if untrackedErr != nil {
571→		fmt.Fprintf(os.Stderr, "Warning: could not list untracked files for preview: %v\n", untrackedErr)
572→		return &RewindPreview{
573→			FilesToRestore: filesToRestore,
574→			FilesToDelete:  filesToDelete,
575→		}, nil
576→	}
577→	for _, relPath := range untrackedNow {
578→		if checkpointFiles[relPath] {
579→			continue
580→		}
581→		if trackedFiles[relPath] {
582→			continue
583→		}
584→		if preservedUntrackedFiles[relPath] {
585→			continue
586→		}
587→		filesToDelete = append(filesToDelete, relPath)
588→	}
589→
590→	// Sort for consistent output
591→	sort.Strings(filesToRestore)
592→	sort.Strings(filesToDelete)
593→
594→	return &RewindPreview{
595→		FilesToRestore: filesToRestore,
596→		FilesToDelete:  filesToDelete,
597→	}, nil
598→}
