600→// RestoreLogsOnly restores session logs from a logs-only rewind point.
601→// This fetches the transcript from entire/checkpoints/v1 and writes it to the agent's session directory.
602→// Does not modify the working directory.
603→// When multiple sessions were condensed to the same checkpoint, ALL sessions are restored.
604→// If force is false, prompts for confirmation when local logs have newer timestamps.
605→// Returns info about each restored session so callers can print correct per-session resume commands.
606→func (s *ManualCommitStrategy) RestoreLogsOnly(ctx context.Context, point RewindPoint, force bool) ([]RestoredSession, error) {
607→	if !point.IsLogsOnly {
608→		return nil, errors.New("not a logs-only rewind point")
609→	}
610→
611→	if point.CheckpointID.IsEmpty() {
612→		return nil, errors.New("missing checkpoint ID")
613→	}
614→
615→	// Get checkpoint store
616→	store, err := s.getCheckpointStore()
617→	if err != nil {
618→		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
619→	}
620→
621→	// Read checkpoint summary to get session count
622→	summary, err := store.ReadCommitted(ctx, point.CheckpointID)
623→	if err != nil {
624→		return nil, fmt.Errorf("failed to read checkpoint: %w", err)
625→	}
626→	if summary == nil {
627→		return nil, fmt.Errorf("checkpoint not found: %s", point.CheckpointID)
628→	}
629→
630→	// Get worktree root for agent session directory lookup
631→	repoRoot, err := paths.WorktreeRoot(ctx)
632→	if err != nil {
633→		return nil, fmt.Errorf("failed to get worktree root: %w", err)
634→	}
635→
636→	// Check for newer local logs if not forcing
637→	if !force {
638→		sessions := s.classifySessionsForRestore(ctx, repoRoot, store, point.CheckpointID, summary)
639→		hasConflicts := false
640→		for _, sess := range sessions {
641→			if sess.Status == StatusLocalNewer {
642→				hasConflicts = true
643→				break
644→			}
645→		}
646→		if hasConflicts {
647→			shouldOverwrite, promptErr := PromptOverwriteNewerLogs(sessions)
648→			if promptErr != nil {
649→				return nil, promptErr
650→			}
651→			if !shouldOverwrite {
652→				fmt.Fprintf(os.Stderr, "Resume cancelled. Local session logs preserved.\n")
653→				return nil, nil
654→			}
655→		}
656→	}
657→
658→	// Count sessions to restore
659→	totalSessions := len(summary.Sessions)
660→	if totalSessions > 1 {
661→		fmt.Fprintf(os.Stderr, "Restoring %d sessions from checkpoint:\n", totalSessions)
662→	}
663→
664→	// Restore all sessions (oldest to newest, using 0-based indexing)
665→	var restored []RestoredSession
666→	for i := range totalSessions {
667→		content, readErr := store.ReadSessionContent(ctx, point.CheckpointID, i)
668→		if readErr != nil {
669→			fmt.Fprintf(os.Stderr, "  Warning: failed to read session %d: %v\n", i, readErr)
670→			continue
671→		}
672→		if content == nil || len(content.Transcript) == 0 {
673→			continue
674→		}
675→
676→		sessionID := content.Metadata.SessionID
677→		if sessionID == "" {
678→			fmt.Fprintf(os.Stderr, "  Warning: session %d has no session ID, skipping\n", i)
679→			continue
680→		}
681→
682→		// Resolve per-session agent from metadata — skip if agent is unknown
683→		if content.Metadata.Agent == "" {
684→			fmt.Fprintf(os.Stderr, "  Warning: session %d (%s) has no agent metadata, skipping (cannot determine target directory)\n", i, sessionID)
685→			continue
686→		}
687→		sessionAgent, agErr := ResolveAgentForRewind(content.Metadata.Agent)
688→		if agErr != nil {
689→			fmt.Fprintf(os.Stderr, "  Warning: session %d (%s) has unknown agent %q, skipping\n", i, sessionID, content.Metadata.Agent)
690→			continue
691→		}
692→
693→		// Compute transcript path from current repo location for cross-machine portability.
694→		sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
695→		if dirErr != nil {
696→			fmt.Fprintf(os.Stderr, "  Warning: failed to get session dir for session %d: %v\n", i, dirErr)
697→			continue
698→		}
699→		sessionFile := sessionAgent.ResolveSessionFile(sessionAgentDir, sessionID)
700→
701→		// Get first prompt for display
702→		promptPreview := ExtractFirstPrompt(content.Prompts)
703→
704→		if totalSessions > 1 {
705→			isLatest := i == totalSessions-1
706→			if promptPreview != "" {
707→				if isLatest {
708→					fmt.Fprintf(os.Stderr, "  Session %d (latest): %s\n", i+1, promptPreview)
709→				} else {
710→					fmt.Fprintf(os.Stderr, "  Session %d: %s\n", i+1, promptPreview)
711→				}
712→			}
713→			fmt.Fprintf(os.Stderr, "    Writing to: %s\n", sessionFile)
714→		} else {
715→			fmt.Fprintf(os.Stderr, "Writing transcript to: %s\n", sessionFile)
716→		}
717→
718→		// Ensure parent directory exists (session file may be in a different dir than sessionAgentDir)
719→		if mkdirErr := os.MkdirAll(filepath.Dir(sessionFile), 0o750); mkdirErr != nil {
720→			fmt.Fprintf(os.Stderr, "    Warning: failed to create directory: %v\n", mkdirErr)
721→			continue
722→		}
723→
724→		agentSession := &agent.AgentSession{
725→			SessionID:  sessionID,
726→			AgentName:  sessionAgent.Name(),
727→			RepoPath:   repoRoot,
728→			SessionRef: sessionFile,
729→			NativeData: content.Transcript,
730→		}
731→		if writeErr := sessionAgent.WriteSession(ctx, agentSession); writeErr != nil {
732→			if totalSessions > 1 {
733→				fmt.Fprintf(os.Stderr, "    Warning: failed to write session: %v\n", writeErr)
734→				continue
735→			}
736→			return nil, fmt.Errorf("failed to write session: %w", writeErr)
737→		}
738→
739→		restored = append(restored, RestoredSession{
740→			SessionID: sessionID,
741→			Agent:     sessionAgent.Type(),
742→			Prompt:    promptPreview,
743→			CreatedAt: content.Metadata.CreatedAt,
744→		})
745→	}
746→
747→	return restored, nil
748→}
