759→// readSessionPrompt reads the first prompt from the session's prompt.txt file stored in git.
760→// Returns an empty string if the prompt cannot be read.
761→func readSessionPrompt(repo *git.Repository, commitHash plumbing.Hash, metadataDir string) string {
762→	// Get the commit and its tree
763→	commit, err := repo.CommitObject(commitHash)
764→	if err != nil {
765→		return ""
766→	}
767→
768→	tree, err := commit.Tree()
769→	if err != nil {
770→		return ""
771→	}
772→
773→	// Look for prompt.txt in the metadata directory
774→	promptPath := metadataDir + "/" + paths.PromptFileName
775→	promptEntry, err := tree.File(promptPath)
776→	if err != nil {
777→		return ""
778→	}
779→
780→	content, err := promptEntry.Contents()
781→	if err != nil {
782→		return ""
783→	}
784→
785→	return ExtractFirstPrompt(content)
786→}
