788→// SessionRestoreStatus represents the status of a session being restored.
789→type SessionRestoreStatus int
790→
791→const (
792→	StatusNew             SessionRestoreStatus = iota // Local file doesn't exist
793→	StatusUnchanged                                   // Local and checkpoint are the same
794→	StatusCheckpointNewer                             // Checkpoint has newer entries
795→	StatusLocalNewer                                  // Local has newer entries (conflict)
796→)
797→
798→// SessionRestoreInfo contains information about a session being restored.
799→type SessionRestoreInfo struct {
800→	SessionID      string
801→	Prompt         string               // First prompt preview for display
802→	Status         SessionRestoreStatus // Status of this session
803→	LocalTime      time.Time
804→	CheckpointTime time.Time
805→}
806→
807→// classifySessionsForRestore checks all sessions in a checkpoint and returns info
808→// about each session, including whether local logs have newer timestamps.
809→// repoRoot is used to compute per-session agent directories.
810→// Sessions without agent metadata are skipped (cannot determine target directory).
811→func (s *ManualCommitStrategy) classifySessionsForRestore(ctx context.Context, repoRoot string, store cpkg.Store, checkpointID id.CheckpointID, summary *cpkg.CheckpointSummary) []SessionRestoreInfo {
812→	var sessions []SessionRestoreInfo
813→
814→	totalSessions := len(summary.Sessions)
815→	// Check all sessions (0-based indexing)
816→	for i := range totalSessions {
817→		content, err := store.ReadSessionContent(ctx, checkpointID, i)
818→		if err != nil || content == nil || len(content.Transcript) == 0 {
819→			continue
820→		}
821→
822→		sessionID := content.Metadata.SessionID
823→		if sessionID == "" || content.Metadata.Agent == "" {
824→			continue
825→		}
826→
827→		sessionAgent, agErr := ResolveAgentForRewind(content.Metadata.Agent)
828→		if agErr != nil {
829→			continue
830→		}
831→
832→		// Compute transcript path from current repo location for cross-machine portability.
833→		sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
834→		if dirErr != nil {
835→			continue
836→		}
837→		localPath := sessionAgent.ResolveSessionFile(sessionAgentDir, sessionID)
838→
839→		localTime := paths.GetLastTimestampFromFile(localPath)
840→		checkpointTime := paths.GetLastTimestampFromBytes(content.Transcript)
841→		status := ClassifyTimestamps(localTime, checkpointTime)
842→
843→		sessions = append(sessions, SessionRestoreInfo{
844→			SessionID:      sessionID,
845→			Prompt:         ExtractFirstPrompt(content.Prompts),
846→			Status:         status,
847→			LocalTime:      localTime,
848→			CheckpointTime: checkpointTime,
849→		})
850→	}
851→
852→	return sessions
853→}
854→
855→// ClassifyTimestamps determines the restore status based on local and checkpoint timestamps.
856→func ClassifyTimestamps(localTime, checkpointTime time.Time) SessionRestoreStatus {
857→	// Local file doesn't exist (no timestamp found)
858→	if localTime.IsZero() {
859→		return StatusNew
860→	}
861→
862→	// Can't determine checkpoint time - treat as new/safe
863→	if checkpointTime.IsZero() {
864→		return StatusNew
865→	}
866→
867→	// Compare timestamps
868→	if localTime.After(checkpointTime) {
869→		return StatusLocalNewer
870→	}
871→	if checkpointTime.After(localTime) {
872→		return StatusCheckpointNewer
873→	}
874→	return StatusUnchanged
875→}
876→
877→// StatusToText returns a human-readable status string.
878→func StatusToText(status SessionRestoreStatus) string {
879→	switch status {
880→	case StatusNew:
881→		return "(new)"
882→	case StatusUnchanged:
883→		return "(unchanged)"
884→	case StatusCheckpointNewer:
885→		return "(checkpoint is newer)"
886→	case StatusLocalNewer:
887→		return "(local is newer)" // shouldn't appear in non-conflict list
888→	default:
889→		return ""
890→	}
891→}
892→
893→// PromptOverwriteNewerLogs asks the user for confirmation to overwrite local
894→// session logs that have newer timestamps than the checkpoint versions.
895→func PromptOverwriteNewerLogs(sessions []SessionRestoreInfo) (bool, error) {
896→	// Separate conflicting and non-conflicting sessions
897→	var conflicting, nonConflicting []SessionRestoreInfo
898→	for _, s := range sessions {
899→		if s.Status == StatusLocalNewer {
900→			conflicting = append(conflicting, s)
901→		} else {
902→			nonConflicting = append(nonConflicting, s)
903→		}
904→	}
905→
906→	fmt.Fprintf(os.Stderr, "\nWarning: Local session log(s) have newer entries than the checkpoint:\n")
907→	for _, info := range conflicting {
908→		// Show prompt if available, otherwise fall back to session ID
909→		if info.Prompt != "" {
910→			fmt.Fprintf(os.Stderr, "  \"%s\"\n", info.Prompt)
911→		} else {
912→			fmt.Fprintf(os.Stderr, "  Session: %s\n", info.SessionID)
913→		}
914→		fmt.Fprintf(os.Stderr, "    Local last entry:      %s\n", info.LocalTime.Local().Format("2006-01-02 15:04:05"))
915→		fmt.Fprintf(os.Stderr, "    Checkpoint last entry: %s\n", info.CheckpointTime.Local().Format("2006-01-02 15:04:05"))
916→	}
917→
918→	// Show non-conflicting sessions with their status
919→	if len(nonConflicting) > 0 {
920→		fmt.Fprintf(os.Stderr, "\nThese other session(s) will also be restored:\n")
921→		for _, info := range nonConflicting {
922→			statusText := StatusToText(info.Status)
923→			if info.Prompt != "" {
924→				fmt.Fprintf(os.Stderr, "  \"%s\" %s\n", info.Prompt, statusText)
925→			} else {
926→				fmt.Fprintf(os.Stderr, "  Session: %s %s\n", info.SessionID, statusText)
927→			}
928→		}
929→	}
930→
931→	fmt.Fprintf(os.Stderr, "\nOverwriting will lose the newer local entries.\n\n")
932→
933→	var confirmed bool
934→	form := huh.NewForm(
935→		huh.NewGroup(
936→			huh.NewConfirm().
937→				Title("Overwrite local session logs with checkpoint versions?").
938→				Value(&confirmed),
939→		),
940→	)
941→	if isAccessibleMode() {
942→		form = form.WithAccessible(true)
943→	}
944→
945→	if err := form.Run(); err != nil {
946→		if errors.Is(err, huh.ErrUserAborted) {
947→			return false, nil
948→		}
949→		return false, fmt.Errorf("failed to get confirmation: %w", err)
950→	}
951→
952→	return confirmed, nil
953→}
