	t.Run("multiple IDs returns latest by CreatedAt", func(t *testing.T) {
		t.Parallel()
		info, found := resolveLatestCheckpointFromMap(
			[]id.CheckpointID{"aaa111bbb222", "ccc333ddd444", "eee555fff666"},
			mapWithThree,
		)
		if !found {
			t.Fatal("expected found=true")
		}
		if info.CheckpointID != "ccc333ddd444" {
			t.Errorf("got %s, want ccc333ddd444 (the newest)", info.CheckpointID)
		}
	})

	t.Run("IDs not in map are skipped", func(t *testing.T) {
		t.Parallel()
		info, found := resolveLatestCheckpointFromMap(
			[]id.CheckpointID{"nonexistent00", "aaa111bbb222"},
			mapWithThree,
		)
		if !found {
			t.Fatal("expected found=true")
		}
		if info.CheckpointID != "aaa111bbb222" {
			t.Errorf("got %s, want aaa111bbb222", info.CheckpointID)
		}
	})

	t.Run("all IDs missing from map returns not found", func(t *testing.T) {
		t.Parallel()
		_, found := resolveLatestCheckpointFromMap(
			[]id.CheckpointID{"nonexistent00", "alsonotthere"},
			mapWithThree,
		)
		if found {
			t.Error("expected found=false when no IDs match")
		}
	})

	t.Run("empty ID list returns not found", func(t *testing.T) {
		t.Parallel()
		_, found := resolveLatestCheckpointFromMap(
			[]id.CheckpointID{},
			mapWithThree,
		)
		if found {
			t.Error("expected found=false for empty list")
		}
	})
}

func TestResolveAgentForRewind(t *testing.T) {
	t.Parallel()

	t.Run("empty type returns error", func(t *testing.T) {
		t.Parallel()
		_, err := ResolveAgentForRewind("")
		if err == nil {
			t.Error("expected error for empty agent type")
		}
	})

	t.Run("Claude Code type resolves correctly", func(t *testing.T) {
		t.Parallel()
		ag, err := ResolveAgentForRewind("Claude Code")
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if ag.Name() != agent.AgentNameClaudeCode {
			t.Errorf("Name() = %q, want %q", ag.Name(), agent.AgentNameClaudeCode)
		}
	})

	t.Run("Gemini CLI type resolves correctly", func(t *testing.T) {
		t.Parallel()
		ag, err := ResolveAgentForRewind("Gemini CLI")
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if ag.Name() != agent.AgentNameGemini {
			t.Errorf("Name() = %q, want %q", ag.Name(), agent.AgentNameGemini)
		}
	})

	t.Run("unknown type returns error", func(t *testing.T) {
		t.Parallel()
		_, err := ResolveAgentForRewind("Nonexistent Agent")
		if err == nil {
			t.Error("expected error for unknown agent type")
		}
	})
}

